    "web_github_search.py", "web_developer_search.py",
]


def read(rel):
    with open(os.path.join(SRC, rel), "rb") as f:
        return f.read()


# =============================================================================
#  Windows installer (.bat)
# =============================================================================

def b64_chunked(data, width=76):
    """Return list of <=width-char base64 lines."""
    s = base64.b64encode(data).decode("ascii")
    return [s[i:i+width] for i in range(0, len(s), width)]


def gen_bat():
    out = []
    ap = out.append

    ap('@echo off')
    ap('setlocal enableDelayedExpansion')
    ap('title Local Search - Installer')
    ap('REM  Prompts run on a code page other than 65001: while the console is on 65001')
    ap('REM  (UTF-8), set /p returns an empty line for redirected or piped stdin, so')
    ap('REM  scripted answers are lost. The code page the console started on is used, or')
    ap('REM  437 when it is already 65001 (chcp persists after a script ends). UTF-8 is')
    ap('REM  enabled after the last prompt.')
    ap('set "LS_PROMPT_CP=437"')
    ap('for /f "tokens=2 delims=:" %%c in (\'chcp\') do for /f %%n in ("%%c") do set "LS_PROMPT_CP=%%n"')
    ap('if "!LS_PROMPT_CP!"=="65001" set "LS_PROMPT_CP=437"')
    ap('chcp !LS_PROMPT_CP! >nul 2>&1')
    ap('')
    ap('REM ===========================================================================')
    ap('REM  Local Search Installer  (Firecrawl + SearXNG + local-web-search skill)  -  Windows')
    ap('REM ===========================================================================')
    ap('REM  Self-contained: every file the installer needs is embedded below as')
    ap('REM  base64. If a source file is missing from this script\'s folder (e.g. you')
    ap('REM  only downloaded this one .bat), the embedded copy is used instead.')
    ap('REM  After installing the stack it also copies the bundled local-web-search agent')
    ap('REM  skill into %USERPROFILE%\\.agents\\skills\\local-web-search.')
    ap('REM  It also asks which browser rendering engine Firecrawl should use -')
    ap('REM  Playwright (default) or Browserless (stealth mode, better block')
    ap('REM  avoidance) - and writes COMPOSE_PROFILES so only that one starts.')
    ap('REM  The installer asks a y/N "Add a Firecrawl account?" question (default N):')
