    ap('if not defined DD_EXE if exist "%LOCALAPPDATA%\\Programs\\Docker Desktop\\Docker Desktop.exe" set "DD_EXE=%LOCALAPPDATA%\\Programs\\Docker Desktop\\Docker Desktop.exe"')
