    ap('if /i "!FIRECRAWL_PORT!"=="!SEARXNG_PORT!" ( echo   [WARNING] Firecrawl port must differ from SearXNG port. & echo. & goto ask_firecrawl )')
    ap('')
    ap('echo.')
    ap('echo --- Step 4 of 6: Browser rendering engine (default: Playwright) ---')
    ap('echo   Firecrawl needs a headless-browser service for JS-rendered pages.')
    ap('echo   1^) Playwright  - the classic Firecrawl engine ^(default^).')
    ap('echo   2^) Browserless - stealth mode ^(masks automation fingerprints^);')
    ap('echo                    better at avoiding Cloudflare/bot-check blocks.')
