unquote() {  # strip one pair of surrounding quotes (pasted / dragged paths)
  local s="$1" q1="'" q2='"'
  s="${s#"$q1"}"; s="${s%"$q1"}"
  s="${s#"$q2"}"; s="${s%"$q2"}"
  printf '%s' "$s"
}
'''

SH_STEP1_PROMPT = r'''
