'''

SH_UPDATE_PROMPTS = r'''
  hdr "Update the repo"
  PY="$(command -v python3 || command -v python || true)"
  if [ -z "$PY" ]; then
    err "python3 (or python) is required to build the installers. Nothing was changed."
    exit 1
  fi
  REPO_DEFAULT=""
  if [ -e "$SCRIPT_DIR/../.git" ] && [ -d "$SCRIPT_DIR/../full-dev-rig" ]; then
    REPO_DEFAULT="$(cd "$SCRIPT_DIR/.." && pwd)"
  fi
  NEED_CONFIRM=0
  if [ -n "$REPO_DEFAULT" ]; then
    REPO="$REPO_DEFAULT"
    say "  Repo: $REPO (detected)"
  else
    NEED_CONFIRM=1
    printf "  Repo folder (the one that contains .git): "
    read -r REPO || REPO=""
    REPO="$(unquote "$REPO")"
    if [ "${REPO#\~}" != "$REPO" ]; then REPO="$HOME${REPO#\~}"; fi  # POSIX tilde expansion
  fi
  if [ -z "$REPO" ] || [ ! -d "$REPO" ]; then
    err "Repo folder not found: ${REPO:-<none given>}. Nothing was changed."
    exit 1
  fi
  REPO="$(cd "$REPO" && pwd)"
  if [ ! -e "$REPO/.git" ]; then
    err "$REPO has no .git folder - refusing to touch it."
    exit 1
  fi
  if [ ! -d "$REPO/full-dev-rig" ]; then
    err "$REPO has no full-dev-rig folder - this does not look like the local-search repo. Nothing was changed."
    exit 1
  fi
  echo
  say "  These items in the repo will be ${BOLD}DELETED${RESET} (everything except .git, .github, full-dev-rig):"
  DEL_LIST="$(find "$REPO" -mindepth 1 -maxdepth 1 ! -name .git ! -name .github ! -name full-dev-rig | sort)"
  if [ -z "$DEL_LIST" ]; then
    say "    (nothing)"
  else
    printf '%s\n' "$DEL_LIST" | while IFS= read -r item; do printf '    - %s\n' "$(basename "$item")"; done
  fi
  echo
  say "  Then the freshly built local-search files are copied into the repo root."
  say "  Nothing is committed - review with git status / git diff afterwards."
  if [ "$NEED_CONFIRM" = "1" ]; then
    printf "Proceed? [Y/n]: "
    read -r CONFIRM || CONFIRM=""
    if [ "$(lower "$CONFIRM")" = "n" ]; then say "Cancelled."; exit 0; fi
  fi
  STAGE="$(mktemp -d "${TMPDIR:-/tmp}/local-search-update.XXXXXX")" || { err "Could not create a temp folder."; exit 1; }
  trap 'rm -rf "$STAGE"' EXIT
  TARGET="$STAGE"
  BUILDNOW="n"
'''

SH_UPDATE_APPLY = r'''
if [ "$MODE" = "update" ]; then
  hdr "Update: build"
  say "Building installers with $PY ..."
  if ! (cd "$STAGE" && "$PY" gen_installers.py >/dev/null); then
    err "gen_installers.py failed - the repo was NOT modified."
    exit 1
  fi
  for f in local-search/install-local-search.sh local-search/install-local-search.bat \
           local-search/docker-compose.yml local-search/README.md; do
    [ -s "$STAGE/$f" ] || { err "Missing after the build: $f - the repo was NOT modified."; exit 1; }
  done
  say "Regenerating the rig packers ..."
  if ! (cd "$STAGE" && "$PY" gen_rig.py >/dev/null); then
    err "gen_rig.py failed - the repo was NOT modified."
    exit 1
  fi
  for f in local-search-rig.sh local-search-rig.bat; do
    [ -s "$STAGE/$f" ] || { err "Missing after gen_rig.py: $f - the repo was NOT modified."; exit 1; }
  done

  hdr "Update: applying to $REPO"
  # 1. replace the rig packers in full-dev-rig (never overwrite the running script)
  for f in local-search-rig.sh local-search-rig.bat; do
    dst="$REPO/full-dev-rig/$f"
    if [ -e "$dst" ] && [ "$dst" -ef "$0" ]; then
      if cmp -s "$STAGE/$f" "$dst"; then
        say "  = full-dev-rig/$f (this is the running script - already up to date)"
      else
        say "  ${YELLOW}[WARN]${RESET} full-dev-rig/$f is the running script and differs from the regenerated one - left as is"
      fi
    else
      cp -f "$STAGE/$f" "$dst" && say "  + full-dev-rig/$f replaced"
    fi
  done
  chmod +x "$REPO/full-dev-rig/local-search-rig.sh" 2>/dev/null || true
  # 2. delete everything except .git, .github and full-dev-rig
  find "$REPO" -mindepth 1 -maxdepth 1 ! -name .git ! -name .github ! -name full-dev-rig -exec rm -rf {} +
  say "  - old files removed"
  # 3. copy the freshly built tree into the repo root (dotfiles included)
  for n in .git .github full-dev-rig; do rm -rf "$STAGE/local-search/$n"; done
  if ! cp -pR "$STAGE/local-search/." "$REPO/"; then
    err "Copy failed after the old files were removed. Restore with: git -C \"$REPO\" checkout -- ."
    exit 1
  fi
  say "  + new files copied into the repo root"
  # record every *.sh as executable (100755) in git. Needed because the bit is lost
  # whenever files travel through Windows (and Git for Windows ignores file modes).
  if command -v git >/dev/null 2>&1; then
    if git -C "$REPO" add --chmod=+x -- '*.sh' >/dev/null 2>&1; then
      (cd "$REPO" && git ls-files -- '*.sh' | while IFS= read -r f; do chmod +x "$f"; done) || true
      say "  + *.sh files marked executable in git (100755)"
    fi
  fi
  ok "Repo updated: $REPO"
  if command -v git >/dev/null 2>&1; then
    echo
    say "  git status (short):"
    (cd "$REPO" && git status --short | head -40)
  fi
  echo
  say "  Next: review the changes, then commit and push."
  say "  (Bump .github/VERSION first if this is a new release.)"
  exit 0
fi
'''


# =============================================================================
#  Windows packer (.bat)
# =============================================================================

def gen_bat_packer():
    out = []
    ap = out.append

    ap('@echo off')
    ap('setlocal enableDelayedExpansion')
    ap('title Local Search Dev Rig - Unpack')
    ap('REM  Prompts run on a code page other than 65001: while the console is on 65001')
    ap('REM  (UTF-8), set /p returns an empty line for redirected or piped stdin, so')
    ap('REM  scripted answers are lost. The code page the console started on is used, or')
    ap('REM  437 when it is already 65001 (chcp persists after a script ends). UTF-8 is')
    ap('REM  enabled after the last prompt.')
    ap('set "LS_PROMPT_CP=437"')
    ap('for /f "tokens=2 delims=:" %%c in (\'chcp\') do for /f %%n in ("%%c") do set "LS_PROMPT_CP=%%n"')
    ap('if "!LS_PROMPT_CP!"=="65001" set "LS_PROMPT_CP=437"')
    ap('chcp !LS_PROMPT_CP! >nul 2>&1')
    ap('')
    ap('REM ===========================================================================')
    ap('REM  Local Search DEV RIG packer  -  Windows')
    ap('REM ===========================================================================')
    ap('REM  Self-contained: embeds the complete build/test environment for the')
    ap('REM  local-search installers:')
    ap('REM    * the local-search source tree (%d files)' % len(SOURCE_FILES))
    ap('REM    * gen_installers.py / gen_rig.py (the two generators)')
    ap('REM    * every test + build script + BUILD.md')
    ap('REM  First prompt: a folder path (or Enter) = unpack the rig there,')
    ap('REM  1 = update the repo automatically. Unpack anywhere, then run build.bat (or: python gen_installers.py) to')
    ap('REM  regenerate the installers, and: python gen_rig.py to regenerate these')
    ap('REM  packers byte-for-byte.')
    ap('REM ===========================================================================')
    ap('')
    ap('echo ============================================================')
    ap('echo   Local Search DEV RIG  (build + test environment)')
    ap('echo   Unpacks everything needed to regenerate and verify the')
    ap('echo   install-local-search installers.')
    ap('echo ============================================================')
    ap('echo.')
    ap('')
    # Prompts
    ap('set "DEFAULT_TARGET=%~dp0local-search-dev"')
    _emit(ap, BAT_PRE)
    ap('')
    ap('echo --- Step 1 of 3: Unpack location ---------------------------')
    ap('echo   Default: %DEFAULT_TARGET%')
    _emit(ap, BAT_STEP1_PROMPT)
    ap('if "!TARGET!"=="" set "TARGET=%DEFAULT_TARGET%"')
    ap('set "TARGET=!TARGET:"=!"')
    ap('for %%I in ("!TARGET!") do set "TARGET=%%~fI"')
    ap('echo   Using: !TARGET!')
    ap('echo   ^(existing files in the target folder are overwritten^)')
    ap('echo.')
    ap('')
    ap('echo --- Step 2 of 3: Build now? --------------------------------')
    ap('echo   Generate install-local-search.bat/.sh with Python right after unpacking?')
    ap('set "BUILDNOW="')
    ap('set /p BUILDNOW="  Run the installer build now? [Y/n]: "')
    ap('echo.')
    ap('')
    ap('echo --- Step 3 of 3: Confirm -----------------------------------')
    ap('echo   Will unpack %d files into: !TARGET!' % N_FILES)
    ap('set "CONFIRM="')
    ap('set /p CONFIRM="Proceed? [Y/n]: "')
    ap('if /i "!CONFIRM!"=="n" ( echo Cancelled. & pause & exit /b 0 )')
    ap('goto :prompts_done')
    ap('')
    _emit(ap, BAT_UPDATE_PROMPTS)
    ap('')
    ap(':prompts_done')
    ap('REM  All prompts are answered - safe to switch to UTF-8 for the output phase.')
    ap('chcp 65001 >nul')
    ap('')
    # Folders
    ap('if not exist "!TARGET!" mkdir "!TARGET!"')
    ap('if not exist "!TARGET!\\local-search" mkdir "!TARGET!\\local-search"')
    ap('if not exist "!TARGET!\\local-search\\config\\searxng" mkdir "!TARGET!\\local-search\\config\\searxng"')
    ap('if not exist "!TARGET!\\local-search\\local-web-search\\scripts" mkdir "!TARGET!\\local-search\\local-web-search\\scripts"')
    ap('if not exist "!TARGET!\\local-search\\invisible-playwright" mkdir "!TARGET!\\local-search\\invisible-playwright"')
    ap('')
    ap('echo Unpacking files...')

    def b64_block(label, data, out_win):
        lines = b64_chunked(data)
        tag = "LSR" + str(zlib.crc32(label.encode("utf-8")) & 0xFFFFFFFF)
        ap('')
        ap('REM --- ' + label + ' ---')
        ap('set "B64TMP=%TEMP%\\' + tag + '.b64"')
        first = True
        for ln in lines:
            ap(('> ' if first else '>> ') + '"!B64TMP!" echo ' + ln)
            first = False
        ap('set "LS_B64_IN=!B64TMP!"')
        ap('set "LS_B64_OUT=' + out_win + '"')
        ap('call :decode_b64')
        ap('del /Q "!B64TMP!" >nul 2>&1')

    # local-search sources
    for rel in SOURCE_FILES:
        label = "local-search/" + rel
        b64_block(label, read_src(rel), '!TARGET!\\local-search\\' + rel.replace("/", "\\"))
    # rig files
    for rel in RIG_FILES:
        b64_block(rel, read_root(rel), '!TARGET!\\' + rel.replace("/", "\\"))

    ap('')
    ap('REM Keep a copy of this packer in the target so the rig is complete.')
    ap('copy /Y "%~f0" "!TARGET!\\local-search-rig.bat" >nul 2>&1')
    ap('echo   Done - %d files + this packer.' % N_FILES)
    ap('if "!MODE!"=="update" goto :update_apply')
    ap('')
    # Optional build
    ap('if /i not "!BUILDNOW!"=="n" (')
    ap('  set "PY="')
    ap('  py -3 -c "print(1)" >nul 2>&1')
    ap('  if not errorlevel 1 set "PY=py -3"')
    ap('  if not defined PY (')
    ap('    python -c "print(1)" >nul 2>&1')
    ap('    if not errorlevel 1 set "PY=python"')
    ap('  )')
    ap('  if not defined PY (')
    ap('    python3 -c "print(1)" >nul 2>&1')
    ap('    if not errorlevel 1 set "PY=python3"')
    ap('  )')
    ap('  if not defined PY (')
    ap('    echo.')
    ap('    echo   [WARNING] Python not found - skipping the build.')
    ap('    echo   Install Python 3.8+, then run build.bat in the target folder.')
    ap('  ) else (')
    ap('    echo.')
    ap('    echo Building installers with !PY! ...')
    ap('    pushd "!TARGET!"')
    ap('    !PY! gen_installers.py')
    ap('    if errorlevel 1 (')
    ap('      popd')
    ap('      echo   [ERROR] gen_installers.py failed.')
    ap('      pause')
    ap('      exit /b 1')
    ap('    )')
    ap('    popd')
    ap('    echo   Installers written to !TARGET!\\local-search\\')
    ap('  )')
    ap(')')
    ap('')
    # Done
    ap('echo.')
    ap('echo ============================================================')
    ap('echo   Dev rig ready: !TARGET!')
    ap('echo.')
    ap('echo   Next steps ^(see BUILD.md inside^):')
    ap('echo     build.bat                     rebuild installers + packers + tests')
    ap('echo     python gen_installers.py      rebuild just the installers')
    ap('echo     python gen_rig.py             rebuild these packers')
    ap('echo ============================================================')
    ap('echo.')
    ap('pause')
    ap('exit /b 0')
    ap('')
    _emit(ap, BAT_UPDATE_APPLY)
    ap('')
    ap(':decode_b64')
    ap('REM  %env:LS_B64_IN% = .b64 temp file, %env:LS_B64_OUT% = output path')
    ap('powershell -NoProfile -Command "$in=$env:LS_B64_IN; $out=$env:LS_B64_OUT; [IO.File]::WriteAllBytes($out, [Convert]::FromBase64String(((Get-Content -Raw $in) -replace \'\\s\',\'\')))"')
    ap('exit /b 0')

    return "\r\n".join(out) + "\r\n"


# =============================================================================
#  Linux / macOS packer (.sh)
# =============================================================================

def gen_sh_packer():
    out = []
    ap = out.append

    ap('#!/usr/bin/env bash')
    ap('# =============================================================================')
    ap('#  Local Search DEV RIG packer  -  Linux / macOS / Git Bash')
    ap('# =============================================================================')
    ap('#  Self-contained: embeds the complete build/test environment for the')
    ap('#  local-search installers:')
    ap('#    * the local-search source tree (%d files)' % len(SOURCE_FILES))
    ap('#    * gen_installers.py / gen_rig.py (the two generators)')
    ap('#    * every test + build script + BUILD.md')
    ap('#    * the Windows packer (local-search-rig.bat)')
    ap('#  First prompt: a folder path (or Enter) = unpack the rig there,')
    ap('#  1 = update the repo automatically.')
    ap('#  So this ONE file reproduces the whole rig anywhere, including both')
    ap('#  packers. The installers themselves are generated after unpacking')
    ap('#  (this script offers to do it) with gen_installers.py.')
    ap('# =============================================================================')
    ap('')
    ap('set -u')
    ap('')
    ap('BOLD="\\033[1m"; GREEN="\\033[32m"; YELLOW="\\033[33m"; RED="\\033[31m"; CYAN="\\033[36m"; RESET="\\033[0m"')
    ap('say()  { printf "%b\\n" "$1"; }')
    ap('err()  { printf "%b[ERROR]%b %s\\n" "$RED" "$RESET" "$1" >&2; }')
    ap('ok()   { printf "%b[OK]%b %s\\n" "$GREEN" "$RESET" "$1"; }')
    ap('hdr()  { printf "\\n%b--- %s ---%b\\n" "$CYAN" "$1" "$RESET"; }')
    ap('lower() { printf \'%s\' "$1" | tr \'[:upper:]\' \'[:lower:]\'; }  # bash-3.2 (macOS) safe')
    ap('')
    ap('cat <<\'BANNER\'')
    ap('============================================================')
    ap('  Local Search DEV RIG  (build + test environment)')
    ap('  Unpacks everything needed to regenerate and verify the')
    ap('  install-local-search installers.')
    ap('============================================================')
    ap('BANNER')
    ap('')
    ap('SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"')
    ap('DEFAULT_TARGET="$SCRIPT_DIR/local-search-dev"')
    ap('')
    _emit(ap, SH_PRE)
    ap('')
    ap('hdr "Step 1 of 3: Unpack location"')
    ap('say "  Default: $DEFAULT_TARGET"')
    _emit(ap, SH_STEP1_PROMPT)
    ap('[ -z "$TARGET" ] && TARGET="$DEFAULT_TARGET"')
    ap('if [ "${TARGET#\\~}" != "$TARGET" ]; then TARGET="$HOME${TARGET#\\~}"; fi  # POSIX tilde expansion')
    ap('mkdir -p "$TARGET"')
    ap('TARGET="$(cd "$TARGET" && pwd)"')
    ap('say "  Using: $TARGET"')
    ap('say "  (existing files in the target folder are overwritten)"')
    ap('')
    ap('hdr "Step 2 of 3: Build now?"')
    ap('say "  Generate install-local-search.bat/.sh with Python right after unpacking?"')
    ap('printf "  Run the installer build now? [Y/n]: "')
    ap('read -r BUILDNOW')
    ap('')
    ap('hdr "Step 3 of 3: Confirm"')
    ap('say "  Will unpack %d files into: $TARGET"' % N_FILES)
    ap('printf "Proceed? [Y/n]: "')
    ap('read -r CONFIRM')
    ap('if [ "$(lower "$CONFIRM")" = "n" ]; then say "Cancelled."; exit 0; fi')
    ap('else')
    _emit(ap, SH_UPDATE_PROMPTS)
    ap('fi')
    ap('')
    ap('mkdir -p "$TARGET/local-search/config/searxng" "$TARGET/local-search/local-web-search/scripts" "$TARGET/local-search/invisible-playwright"')
    ap('')
    ap('say "Unpacking files..."')

    def heredoc_block(rel_path, data):
        text = data.decode("utf-8")
        # LF-normalise the heredoc body; the awk loop below restores CRLF for
        # every .bat file after unpacking.
        text_lf = text.replace("\r\n", "\n").replace("\r", "\n")
        tag = tag_for(rel_path)
        ap('')
        ap('# --- ' + rel_path + ' ---')
        ap('cat > "$TARGET/' + rel_path + '" <<\'' + tag + '\'')
        for line in text_lf.splitlines():
            ap(line)
        ap(tag)

    # local-search sources
    for rel in SOURCE_FILES:
        heredoc_block("local-search/" + rel, read_src(rel))
    # rig files
    for rel in RIG_FILES:
        heredoc_block(rel, read_root(rel))
    # the Windows packer, so this one file reproduces the whole rig
    heredoc_block("local-search-rig.bat", read_root("local-search-rig.bat"))

    ap('')
    ap('# Keep a copy of this packer in the target so the rig is complete.')
    ap('cp -f "$0" "$TARGET/local-search-rig.sh"')
    ap('chmod +x "$TARGET"/*.sh "$TARGET"/local-search/*.sh 2>/dev/null || true')
    ap('')
    ap('# Restore CRLF line endings for every .bat file (the heredocs above')
    ap('# wrote LF; awk is used instead of sed so this also works on macOS).')
    ap('find "$TARGET" -type f -name \'*.bat\' 2>/dev/null | while IFS= read -r f; do')
    ap('  awk \'{sub(/\\r$/,""); printf "%s\\r\\n", $0}\' "$f" > "$f.crlf" 2>/dev/null \\')
    ap('    && mv "$f.crlf" "$f" || rm -f "$f.crlf"')
    ap('done')
    ap('')
    ap('ok "Unpacked the dev rig into: $TARGET"')
    ap('')
    _emit(ap, SH_UPDATE_APPLY)
    ap('')
    # Optional build
    ap('if [ "$(lower "${BUILDNOW:-y}")" != "n" ]; then')
    ap('  PY="$(command -v python3 || command -v python)"')
    ap('  if [ -n "$PY" ]; then')
    ap('    say "Building installers with $PY ..."')
    ap('    if (cd "$TARGET" && "$PY" gen_installers.py); then')
    ap('      say "  Installers written to $TARGET/local-search/"')
    ap('    else')
    ap('      err "gen_installers.py failed - see output above."')
    ap('    fi')
    ap('  else')
    ap('    say "  ${YELLOW}[WARNING]${RESET} Python not found - skipping the build."')
    ap('    say "  Install Python 3.8+, then run ./build.sh in the target folder."')
    ap('  fi')
    ap('fi')
    ap('')
    # Done
    ap('echo')
    ap('say "${GREEN}============================================================${RESET}"')
    ap('say "${GREEN}  Dev rig ready: $TARGET${RESET}"')
    ap('echo')
    ap('say "  Next steps (see BUILD.md inside):"')
    ap('say "    ./build.sh                    rebuild installers + packers + tests"')
    ap('say "    python3 gen_installers.py     rebuild just the installers"')
    ap('say "    python3 gen_rig.py            rebuild these packers"')
    ap('say "${GREEN}============================================================${RESET}"')

    return "\n".join(out) + "\n"


def main():
    # Write the .bat packer FIRST: the .sh packer embeds it, so it must read
    # the freshly-written file (not a stale previous-generation copy).
    bat = gen_bat_packer()
    with open(os.path.join(ROOT, "local-search-rig.bat"), "wb") as f:
        f.write(bat.encode("utf-8"))
    sh = gen_sh_packer()
    with open(os.path.join(ROOT, "local-search-rig.sh"), "wb") as f:
        f.write(sh.encode("utf-8"))
    os.chmod(os.path.join(ROOT, "local-search-rig.sh"), 0o755)
    print("Wrote local-search-rig.bat (%d bytes)" % len(bat))
    print("Wrote local-search-rig.sh  (%d bytes)" % len(sh))


if __name__ == "__main__":
    main()
EOF_GEN_RIG_PY

# --- extract-embedded.py ---
cat > "$TARGET/extract-embedded.py" <<'EOF_EXTRACT_EMBEDDED_PY'
#!/usr/bin/env python3
"""Extract the files embedded in a local-search .sh installer or rig packer.

Works on:
    install-local-search.sh    -> extracts the 20 local-search/ source files
                                  (+ install-local-search.bat)
    local-search-rig.sh        -> extracts the COMPLETE dev rig
                                  (local-search/ sources + all rig scripts +
                                  local-search-rig.bat)

No Docker, no execution of the embedded scripts: this just parses the quoted
heredocs (`cat > "$TARGET/<file>" <<'TAG'`) and writes their content to disk.
Line endings are restored (CRLF for .bat files), so the extracted tree is
byte-identical to the sources the packer/generator originally embedded.

Usage:
    python3 extract-embedded.py <install-local-search.sh | local-search-rig.sh> [outdir]

Result:
    outdir/ contains the extracted tree. For the installer, outdir IS the
    local-search folder content; for the rig packer, outdir IS the rig root
    (local-search/ plus the rig scripts). The .sh file you extracted from is
    not itself embedded -- copy it over manually if you want it included.
"""
import argparse
import os
import re
import sys

_HEREDOC = re.compile(r'''^\s*cat > "\$TARGET/(.+?)" <<'([A-Z0-9_]+)'$''')


def main() -> int:
    ap = argparse.ArgumentParser(
        description="Extract files embedded in a local-search .sh installer/packer.")
    ap.add_argument("source", help="install-local-search.sh or local-search-rig.sh")
    ap.add_argument("outdir", nargs="?", default="extracted",
                    help="output directory (default: ./extracted)")
    args = ap.parse_args()

    try:
        with open(args.source, encoding="utf-8") as fh:
            lines = fh.read().split("\n")
    except OSError as e:
        print("cannot read %s: %s" % (args.source, e), file=sys.stderr)
        return 2

    count = 0
    i = 0
    while i < len(lines):
        m = _HEREDOC.match(lines[i])
        if not m:
            i += 1
            continue
        rel, tag = m.group(1), m.group(2)
        j = i + 1
        body = []
        while j < len(lines) and lines[j] != tag:
            body.append(lines[j])
            j += 1
        if j >= len(lines):
            print("unterminated heredoc for %s" % rel, file=sys.stderr)
            return 1
        content = "\n".join(body) + ("\n" if body else "")
        out = os.path.join(args.outdir, *rel.split("/"))
        parent = os.path.dirname(out)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(out, "w", encoding="utf-8", newline="\n") as fh:
            fh.write(content)
        if rel.endswith(".bat"):
            # restore CRLF (the heredoc body was LF-normalised at pack time)
            with open(out, "rb") as fh:
                data = fh.read()
            with open(out, "wb") as fh:
                fh.write(data.replace(b"\r\n", b"\n").replace(b"\n", b"\r\n"))
        print("  extracted %s" % rel)
        count += 1
        i = j + 1

    if count == 0:
        print("no embedded heredocs found in %s "
              "(is it really a local-search .sh artifact?)" % args.source,
              file=sys.stderr)
        return 1
    print("%d files extracted to %s/" % (count, args.outdir))
    return 0


if __name__ == "__main__":
    sys.exit(main())
EOF_EXTRACT_EMBEDDED_PY

# --- test_b64.py ---
cat > "$TARGET/test_b64.py" <<'EOF_TEST_B64_PY'
#!/usr/bin/env python3
"""Simulate the .bat decode_b64 logic for every embedded file and verify
the round-trip matches the original source files."""
import base64
import re
import os

SRC = os.path.join(os.path.dirname(os.path.abspath(__file__)), "local-search")
BAT = os.path.join(SRC, "install-local-search.bat")
SH  = os.path.join(SRC, "install-local-search.sh")

FILES = [
    "config/searxng/settings.yml",
    "docker-compose.yml",
    ".env.example",
    "README.md",
    "LICENSE",
    ".gitignore",
    ".gitattributes",
    "Run.bat", "Stop.bat", "Update.bat", "Uninstall.bat",
    "run.sh", "stop.sh", "update.sh", "uninstall.sh", "engine.sh",
    "local-web-search/SKILL.md",
    "local-web-search/SKILL-core.md",
    "local-web-search/SKILL-llm.md",
    "local-web-search/scripts/config.py",
    "local-web-search/scripts/ensure_stack.py",
    "local-web-search/scripts/firecrawl_api.py",
    "local-web-search/scripts/web_search.py",
    "local-web-search/scripts/web_scrape.py",
    "local-web-search/scripts/web_extract.py",
    "local-web-search/scripts/web_youtube_transcript.py",
    "local-web-search/scripts/web_map.py",
    "local-web-search/scripts/web_crawl.py",
    "local-web-search/scripts/web_crawl_status.py",
    "local-web-search/scripts/web_agent.py",
    "local-web-search/scripts/web_agent_status.py",
    "local-web-search/scripts/web_interact.py",
    "local-web-search/scripts/web_interact_stop.py",
    "local-web-search/scripts/web_parse.py",
    "local-web-search/scripts/web_monitor_create.py",
    "local-web-search/scripts/web_monitor_list.py",
    "local-web-search/scripts/web_monitor_get.py",
    "local-web-search/scripts/web_monitor_update.py",
    "local-web-search/scripts/web_monitor_delete.py",
    "local-web-search/scripts/web_monitor_run.py",
    "local-web-search/scripts/web_monitor_checks.py",
    "local-web-search/scripts/web_monitor_check.py",
    "local-web-search/scripts/web_research_search.py",
    "local-web-search/scripts/web_research_inspect.py",
    "local-web-search/scripts/web_research_related.py",
    "local-web-search/scripts/web_research_read.py",
    "local-web-search/scripts/web_github_search.py",
    "local-web-search/scripts/web_developer_search.py",
]

def read(rel):
    with open(os.path.join(SRC, rel), "rb") as f:
        return f.read()

# ---- extract base64 blocks from the .bat ----
bat_text = open(BAT, "r", encoding="utf-8").read()
# A block looks like:
#   REM --- <rel> ---
#   set "NEED_B64=1"
#   ...
#   set "B64TMP=%TEMP%\LSxxxxxx.b64"
#   > "!B64TMP!" echo LINE1
#   >> "!B64TMP!" echo LINE2
#   ...
#   set "LS_B64_IN=..."
blocks = {}
cur_rel = None
cur_lines = []
for line in bat_text.split("\n"):
    m = re.match(r'REM --- (.+?) ---$', line)
    if m:
        if cur_rel:
            blocks[cur_rel] = cur_lines
        cur_rel = m.group(1)
        cur_lines = []
        continue
    m2 = re.match(r'\s*>>?\s*"!B64TMP!"\s+echo\s+(.+)$', line)
    if m2 and cur_rel:
        cur_lines.append(m2.group(1))
if cur_rel:
    blocks[cur_rel] = cur_lines

print("Found %d embedded base64 blocks in .bat" % len(blocks))
ok = True
for rel in FILES:
    orig = read(rel)
    if rel not in blocks:
        print("  [MISS] %-32s : no base64 block in .bat" % rel)
        ok = False
        continue
    # concatenate and strip whitespace (mirrors PS -replace '\s','')
    joined = "".join(blocks[rel])
    try:
        dec = base64.b64decode(joined)
    except Exception as e:
        print("  [FAIL] %-32s : b64 decode error: %s" % (rel, e))
        ok = False
        continue
    if dec == orig:
        print("  [OK]   %-32s : %d bytes round-trip OK" % (rel, len(orig)))
    else:
        print("  [FAIL] %-32s : decoded %d bytes != original %d bytes" % (rel, len(dec), len(orig)))
        ok = False

# ---- cmd.exe block-paren safety check on the .bat logic lines ----
# Real cmd.exe rule (verified against a real cmd.exe implementation):
#   * an unquoted/unescaped "(" in echo text is INERT (literal text),
#   * but an unquoted/unescaped ")" INSIDE a parenthesized block is
#     STRUCTURAL: it closes the block at that point. If the ")" is in the
#     middle of a command's text, the remainder of the statement becomes
#     top-level garbage -> "FOR was unexpected at this time" (or similar)
#     -> cmd.exe aborts the batch and the window closes.
# So: while a block is open, every unquoted/unescaped ")" must be a
# legitimate closer: a ")"-line, ") else (", or followed by do/&/|/EOL.
def _unquoted_parens(line):
    out = []
    j = 0; inq = False
    while j < len(line):
        c = line[j]
        if c == "^":
            j += 2; continue
        if c == '"':
            inq = not inq; j += 1; continue
        if not inq and c in "()":
            out.append((j, c))
        j += 1
    return out

_close_cont = re.compile(r'^(else\b|do\b|&|\||rem\b|::)', re.I)
b64line = re.compile(r'\s*>>?\s*"?!?B64TMP!?"?\s+echo\s+')
remline = re.compile(r'^\s*(REM\b|::)', re.I)
bat_lines = bat_text.split("\n")
paren_bad = []
depth = 0
for i, line in enumerate(bat_lines):
    if b64line.match(line) or remline.match(line) or not line.strip():
        continue
    # skip embedded-base64 temp-file writes
    ps = _unquoted_parens(line)
    closes = [p for p in ps if p[1] == ")"]
    opens = len([p for p in ps if p[1] == "("])
    # structural opens: "(" at end of line (if/for/do blocks) + inline
    # for-set/do opens ("in (", "do (")
    structural_opens = 0
    if line.rstrip().endswith("("):
        structural_opens += 1
    inline = len(re.findall(r"\bin\s*\(", line)) + len(re.findall(r"\bdo\s*\(", line))
    if line.rstrip().endswith("(") and inline:
        inline = max(0, inline - 1)
    structural_opens += inline
    if depth > 0 and closes:
        for pos, _ch in closes:
            after = line[pos + 1:].lstrip()
            if after == "" or _close_cont.match(after):
                continue  # legitimate closer
            paren_bad.append((i + 1, line.strip()))
            break
    depth += structural_opens - len(closes)
    if depth < 0:
        depth = 0  # top-level ")" in echo text is a literal, harmless
if paren_bad:
    print()
    print("[FAIL] unescaped ')' inside blocks (kills real cmd.exe):")
    for ln, txt in paren_bad:
        print("  L%d: %s" % (ln, txt))
    ok = False
else:
    print("paren check: no unescaped ')' inside blocks (cmd-safe)")

print()
print("ALL GOOD" if ok else "FAILURES PRESENT")
import sys
sys.exit(0 if ok else 1)
EOF_TEST_B64_PY

# --- test_heredocs.py ---
cat > "$TARGET/test_heredocs.py" <<'EOF_TEST_HEREDOCS_PY'
#!/usr/bin/env python3
"""Extract every quoted heredoc from the .sh installer and verify the
content matches the original source files byte-for-byte."""
import os
import re

SRC = os.path.join(os.path.dirname(os.path.abspath(__file__)), "local-search")
SH  = os.path.join(SRC, "install-local-search.sh")
text = open(SH, "r", encoding="utf-8").read()

FILES = [
    "config/searxng/settings.yml", "docker-compose.yml", ".env.example",
    "README.md", "LICENSE", ".gitignore", ".gitattributes",
    "Run.bat", "Stop.bat", "Update.bat", "Uninstall.bat",
    "run.sh", "stop.sh", "update.sh", "uninstall.sh", "engine.sh",
    "local-web-search/SKILL.md",
    "local-web-search/SKILL-core.md",
    "local-web-search/SKILL-llm.md",
    "local-web-search/scripts/config.py",
    "local-web-search/scripts/ensure_stack.py",
    "local-web-search/scripts/firecrawl_api.py",
    "local-web-search/scripts/web_search.py",
    "local-web-search/scripts/web_scrape.py",
    "local-web-search/scripts/web_extract.py",
    "local-web-search/scripts/web_youtube_transcript.py",
    "local-web-search/scripts/web_map.py",
    "local-web-search/scripts/web_crawl.py",
    "local-web-search/scripts/web_crawl_status.py",
    "local-web-search/scripts/web_agent.py",
    "local-web-search/scripts/web_agent_status.py",
    "local-web-search/scripts/web_interact.py",
    "local-web-search/scripts/web_interact_stop.py",
    "local-web-search/scripts/web_parse.py",
    "local-web-search/scripts/web_monitor_create.py",
    "local-web-search/scripts/web_monitor_list.py",
    "local-web-search/scripts/web_monitor_get.py",
    "local-web-search/scripts/web_monitor_update.py",
    "local-web-search/scripts/web_monitor_delete.py",
    "local-web-search/scripts/web_monitor_run.py",
    "local-web-search/scripts/web_monitor_checks.py",
    "local-web-search/scripts/web_monitor_check.py",
    "local-web-search/scripts/web_research_search.py",
    "local-web-search/scripts/web_research_inspect.py",
    "local-web-search/scripts/web_research_related.py",
    "local-web-search/scripts/web_research_read.py",
    "local-web-search/scripts/web_github_search.py",
    "local-web-search/scripts/web_developer_search.py",
    "install-local-search.bat",
]

def read(rel):
    with open(os.path.join(SRC, rel), "rb") as f:
        return f.read()

# Find blocks of the form:
#   cat > "$TARGET/<rel>" <<'<TAG>'
#   <body>
#   <TAG>
heredocs = {}
lines = text.split("\n")
i = 0
while i < len(lines):
    m = re.match(r"\s*cat > \"\$TARGET/(.+?)\" <<'([A-Z0-9_]+)'$", lines[i])
    if m:
        rel, tag = m.group(1), m.group(2)
        body_start = i + 1
        # find closing tag
        j = body_start
        while j < len(lines) and lines[j] != tag:
            j += 1
        body = "\n".join(lines[body_start:j])
        # every heredoc line (including the last) is written with a trailing
        # newline by the shell, so append it back after the join.
        if body_start <= j:
            body += "\n"
        heredocs[rel] = body
        i = j + 1
    else:
        i += 1

print("Found %d heredocs in .sh" % len(heredocs))
ok = True
for rel in FILES:
    orig = read(rel).decode("utf-8")
    if rel not in heredocs:
        print("  [MISS] %-32s" % rel)
        ok = False
        continue
    # Compare content ignoring line-ending differences: the .sh installer
    # writes .bat files via heredoc (LF) and then a runtime CRLF-conversion
    # loop converts them to CRLF. So the heredoc body has LF where the
    # original .bat has CRLF -- this is expected and correct.
    a = heredocs[rel].replace("\r\n", "\n")
    b = orig.replace("\r\n", "\n")
    if a == b:
        print("  [OK]   %-32s : %d bytes (content matches; CRLF fixed at runtime)" % (rel, len(orig)))
    else:
        print("  [FAIL] %-32s : heredoc %d vs orig %d (LF-normalised)" % (rel, len(a), len(b)))
        for k in range(min(len(a), len(b))):
            if a[k] != b[k]:
                print("    first diff at byte %d: heredoc=%r orig=%r" % (k, a[k:k+30], b[k:k+30]))
                break
        ok = False

print()
print("ALL GOOD" if ok else "FAILURES")
EOF_TEST_HEREDOCS_PY

# --- test_rig.py ---
cat > "$TARGET/test_rig.py" <<'EOF_TEST_RIG_PY'
#!/usr/bin/env python3
"""Verify both rig packers (local-search-rig.bat / local-search-rig.sh) embed
the CURRENT files exactly. Run from the rig root after gen_rig.py.

  * local-search-rig.bat : every `REM --- <file> ---` base64 block must
    decode to the exact bytes of the file on disk.
  * local-search-rig.sh  : every `cat > "$TARGET/<file>" <<'TAG'` heredoc
    must match the file on disk (LF-normalised; CRLF is restored for .bat
    files by the packer's awk loop at unpack time).
"""
import base64
import os
import re
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, ROOT)
from gen_rig import RIG_FILES, SOURCE_FILES  # noqa: E402

BAT = os.path.join(ROOT, "local-search-rig.bat")
SH = os.path.join(ROOT, "local-search-rig.sh")

failures = []


def disk_bytes(rel):
    with open(os.path.join(ROOT, *rel.split("/")), "rb") as f:
        return f.read()


# ---- 1. base64 blocks in the .bat packer -----------------------------------
bat_text = open(BAT, encoding="utf-8").read()
blocks = {}
cur, cur_lines = None, []
for line in bat_text.split("\n"):
    m = re.match(r"REM --- (.+?) ---$", line)
    if m:
        if cur is not None:
            blocks[cur] = cur_lines
        cur, cur_lines = m.group(1), []
        continue
    m2 = re.match(r'\s*>>?\s*"!B64TMP!"\s+echo\s+(.+)$', line)
    if m2 and cur is not None:
        cur_lines.append(m2.group(1))
if cur is not None:
    blocks[cur] = cur_lines

expected = ["local-search/" + s for s in SOURCE_FILES] + RIG_FILES
print("local-search-rig.bat: %d embedded base64 blocks" % len(blocks))
for label in expected:
    if label not in blocks:
        failures.append("bat missing block: " + label)
        continue
    try:
        dec = base64.b64decode("".join(blocks[label]))
    except Exception as e:
        failures.append("bat bad base64 %s: %s" % (label, e))
        continue
    want = disk_bytes(label)
    if dec == want:
        print("  [OK]   %-46s %d bytes" % (label, len(want)))
    else:
        failures.append("bat mismatch: %s (%d vs %d bytes)" % (label, len(dec), len(want)))

if 'copy /Y "%~f0"' not in bat_text:
    failures.append("bat packer lost its self-copy line")

# Update mode (first prompt answered "1"): the .bat cannot be executed in CI,
# so lint it statically - every goto/call target must exist as a label, and
# the update markers must be present.
bat_labels = set(re.findall(r"^:([A-Za-z0-9_]+)\s*$", bat_text, re.M))
for tgt in sorted(set(re.findall(r"(?:goto|call)\s+:([A-Za-z0-9_]+)", bat_text, re.I))):
    if tgt not in bat_labels:
        failures.append("bat: goto/call target ':%s' has no label" % tgt)
for marker in (":update_prompts", ":prompts_done", ":update_apply", ":update_fail", ":find_py",
               'if "!TARGET!"=="1" goto :update_prompts', "robocopy ", "gen_installers.py >nul"):
    if marker not in bat_text:
        failures.append("bat packer lost update-mode marker: " + marker)
bat_raw = open(BAT, "rb").read()
if b"\r\n" not in bat_raw or re.search(rb"[^\r]\n", bat_raw):
    failures.append("bat packer must use CRLF line endings only")
else:
    print("  [OK]   bat update-mode labels resolve, markers present, CRLF only")

# ---- 2. heredocs in the .sh packer -----------------------------------------
sh_text = open(SH, encoding="utf-8").read()
for marker in ('if [ "$TARGET" = "1" ]; then MODE=update', 'MODE" = "update"', "gen_installers.py", "-exec rm -rf {} +"):
    if marker not in sh_text:
        failures.append("sh packer lost update-mode marker: " + marker)
lines = sh_text.split("\n")
heredocs = {}
i = 0
while i < len(lines):
    m = re.match(r"\s*cat > \"\$TARGET/(.+?)\" <<'([A-Z0-9_]+)'$", lines[i])
    if m:
        rel, tag = m.group(1), m.group(2)
        j = i + 1
        while j < len(lines) and lines[j] != tag:
            j += 1
        if j >= len(lines):
            failures.append("sh heredoc for %s has no closing tag" % rel)
            i += 1
            continue
        body = "\n".join(lines[i + 1:j])
        if i + 1 <= j:
            body += "\n"
        heredocs[rel] = body
        i = j + 1
    else:
        i += 1

expected_sh = expected + ["local-search-rig.bat"]
print("local-search-rig.sh: %d embedded heredocs" % len(heredocs))
for label in expected_sh:
    if label not in heredocs:
        failures.append("sh missing heredoc: " + label)
        continue
    want = disk_bytes(label).decode("utf-8").replace("\r\n", "\n").replace("\r", "\n")
    got = heredocs[label]
    if got == want:
        print("  [OK]   %-46s %d bytes" % (label, len(want)))
    else:
        failures.append("sh mismatch: %s (%d vs %d bytes)" % (label, len(got), len(want)))

if 'cp -f "$0" "$TARGET/local-search-rig.sh"' not in sh_text:
    failures.append("sh packer lost its self-copy line")
if 'printf "%s\\r\\n", $0' not in sh_text:
    failures.append("sh packer lost its CRLF-restore awk loop")

print()
if failures:
    for f in failures:
        print("  [FAIL] " + f)
    print("TESTS FAILED")
    sys.exit(1)
print("ALL GOOD")
EOF_TEST_RIG_PY

# --- test_invisible_service.py ---
cat > "$TARGET/test_invisible_service.py" <<'EOF_TEST_INVISIBLE_SERVICE_PY'
#!/usr/bin/env python3
"""
Contract test for local-search/invisible-playwright/server.py.

The real engine (a patched Firefox) is a ~260 MB download and is not needed to
check the part this repo owns: the HTTP contract Firecrawl relies on, header and
cookie handling, the SSRF guard, concurrency limiting and browser restart. A
stand-in browser implements just the Playwright calls the service makes.

Needs `aiohttp` (it is installed inside the engine image). Without it the test
SKIPS loudly and exits 0, so a plain Python install can still run the build.
"""
import sys

sys.dont_write_bytecode = True  # never leave __pycache__ inside local-search/

import asyncio
import importlib.util
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
SERVER_PY = os.path.join(HERE, "local-search", "invisible-playwright", "server.py")

try:
    import aiohttp  # noqa: F401
    from aiohttp.test_utils import TestClient, TestServer
except ImportError:
    print("SKIP: aiohttp is not installed - test_invisible_service.py did not run.")
    print("      (pip install aiohttp to enable it; the engine image already has it)")
    sys.exit(0)

spec = importlib.util.spec_from_file_location("invisible_server", SERVER_PY)
srv = importlib.util.module_from_spec(spec)
sys.modules["invisible_server"] = srv
spec.loader.exec_module(srv)

PASS = True

# The guard resolves hostnames; the tests use a fixed table so they never need DNS.
FAKE_DNS = {"example.com": ["93.184.216.34"], "www.example.co.uk": ["93.184.216.34"],
            "slow.example": ["93.184.216.34"], "ads.doubleclick.net": ["93.184.216.34"],
            "localhost": ["127.0.0.1"], "internal.corp": ["10.0.0.9"],
            "mixed.example": ["93.184.216.34", "10.0.0.9"]}


async def fake_resolve(host):
    return FAKE_DNS.get(host, [])


srv.resolve_host = fake_resolve


def check(name, cond, extra=""):
    global PASS
    if cond:
        print("  [OK]   " + name)
    else:
        print("  [FAIL] " + name + (("  -> " + str(extra)) if extra else ""))
        PASS = False


# ---------------------------------------------------------------- stand-in browser
class FakeResponse:
    def __init__(self, status=200, headers=None, body="<html>ok</html>"):
        self.status = status
        self.headers = headers if headers is not None else {"content-type": "text/html; charset=utf-8"}
        self._body = body

    async def text(self):
        return self._body


class FakePage:
    def __init__(self, ctx):
        self.ctx = ctx
        self.html = "<html><body>rendered</body></html>"

    def set_default_timeout(self, ms):
        self.ctx.default_timeout = ms

    async def goto(self, url, wait_until=None, timeout=None):
        self.ctx.browser.log.append(("goto", url, wait_until, timeout))
        self.ctx.browser.active += 1
        self.ctx.browser.peak = max(self.ctx.browser.peak, self.ctx.browser.active)
        try:
            await asyncio.sleep(self.ctx.browser.delay)
            behaviour = self.ctx.browser.pages.get(url)
            if isinstance(behaviour, Exception):
                raise behaviour
            if behaviour is None:
                behaviour = FakeResponse()
            self.html = getattr(behaviour, "html", self.html)
            return behaviour
        finally:
            self.ctx.browser.active -= 1

    async def wait_for_timeout(self, ms):
        self.ctx.browser.log.append(("wait", ms))

    async def wait_for_selector(self, selector, timeout=None):
        self.ctx.browser.log.append(("selector", selector, timeout))
        if selector in self.ctx.browser.missing_selectors:
            raise TimeoutError("selector %s not found" % selector)

    async def content(self):
        return self.html

    async def close(self):
        pass


class FakeContext:
    def __init__(self, browser, kwargs):
        self.browser = browser
        self.kwargs = kwargs
        self.cookies = []
        self.extra_headers = None
        self.routed = False
        self.default_timeout = None
        browser.contexts.append(self)

    async def add_cookies(self, cookies):
        self.cookies.extend(cookies)

    async def set_extra_http_headers(self, headers):
        # the real engine refuses this ("not wired yet"); extra headers are only
        # accepted by new_context(extra_http_headers=...)
        raise RuntimeError("set_extra_http_headers() is not wired yet")

    async def route(self, pattern, handler):
        self.routed = True
        self.handler = handler

    async def new_page(self):
        return FakePage(self)

    async def close(self):
        self.closed = True


class FakeBrowser:
    def __init__(self):
        self.contexts = []
        self.log = []
        self.pages = {}
        self.missing_selectors = set()
        self.delay = 0.0
        self.active = 0
        self.peak = 0
        self.connected = True

    def is_connected(self):
        return self.connected

    async def new_context(self, **kwargs):
        return FakeContext(self, kwargs)


class Factory:
    def __init__(self):
        self.calls = 0
        self.browsers = []
        self.fail = False
        self.cfg_seen = None

    async def __call__(self, stack, cfg):
        self.calls += 1
        self.cfg_seen = cfg
        if self.fail:
            raise RuntimeError("engine missing")
        browser = FakeBrowser()
        self.browsers.append(browser)
        return browser


def make_cfg(**over):
    for k in ("PORT", "MAX_CONCURRENT_PAGES", "BLOCK_MEDIA", "BLOCK_ADS", "ALLOW_LOCAL_WEBHOOKS",
              "PROXY_SERVER", "PROXY_USERNAME", "PROXY_PASSWORD", "INVPW_SEED", "INVPW_TIMEZONE",
              "INVPW_LOCALE", "INVPW_HONOR_USER_AGENT"):
        os.environ.pop(k, None)
    for k, v in over.items():
        os.environ[k] = v
    cfg = srv.Config()
    return cfg


async def with_client(cfg, factory, fn):
    app = srv.create_app(cfg, factory)
    async with TestClient(TestServer(app)) as client:
        await fn(client)


async def post(client, payload):
    resp = await client.post("/scrape", data=json.dumps(payload), headers={"Content-Type": "application/json"})
    try:
        data = await resp.json()
    except Exception:
        data = None
    return resp.status, data


# ---------------------------------------------------------------- scenarios
async def main():
    # 1. input validation ------------------------------------------------------
    print("-- input validation")
    f = Factory()

    async def t1(c):
        s, d = await post(c, {})
        check("missing url -> 400 'URL is required'", s == 400 and d == {"error": "URL is required"}, (s, d))
        s, d = await post(c, {"url": "example.com"})
        check("scheme-less url -> 400 'Invalid URL'", s == 400 and d == {"error": "Invalid URL"}, (s, d))
        s, d = await post(c, {"url": "http://"})
        check("host-less url -> 400 'Invalid URL'", s == 400 and d == {"error": "Invalid URL"}, (s, d))
        s, d = await post(c, {"url": "file:///etc/passwd"})
        check("file:// -> 200 with pageStatusCode 403 (blocked, not fetched)",
              s == 200 and d["pageStatusCode"] == 403 and d["content"] == "", (s, d))
        r = await c.post("/scrape", data="not json", headers={"Content-Type": "application/json"})
        check("garbage body -> 400", r.status == 400, r.status)
    await with_client(make_cfg(ALLOW_LOCAL_WEBHOOKS="true"), f, t1)
    check("no browser page was opened for rejected input", not f.browsers[0].log, f.browsers[0].log)

    # 2. normal scrape + response shape ---------------------------------------
    print("-- scrape result shape")
    f = Factory()

    async def t2(c):
        b = f.browsers[0]
        b.pages["https://example.com/a?token=SECRET"] = FakeResponse(200, {"content-type": "text/html"})
        s, d = await post(c, {"url": "https://example.com/a?token=SECRET", "timeout": 9000, "wait_after_load": 250})
        check("200 html -> content/pageStatusCode/contentType",
              s == 200 and d["pageStatusCode"] == 200 and d["contentType"] == "text/html"
              and "rendered" in d["content"], (s, d))
        check("no pageError on 200", "pageError" not in d, d)
        check("navigates with wait_until=load and the requested timeout",
              ("goto", "https://example.com/a?token=SECRET", "load", 9000) in b.log, b.log)
        check("wait_after_load honoured", ("wait", 250) in b.log, b.log)

        b.pages["https://example.com/missing"] = FakeResponse(404)
        s, d = await post(c, {"url": "https://example.com/missing"})
        check("404 -> pageStatusCode 404 + pageError 'Not Found'",
              s == 200 and d["pageStatusCode"] == 404 and d["pageError"] == "Not Found", (s, d))

        b.pages["https://example.com/api"] = FakeResponse(200, {"content-type": "application/json"}, '{"a": 1}')
        s, d = await post(c, {"url": "https://example.com/api"})
        check("application/json returns the raw body, not page.content()",
              d["content"] == '{"a": 1}' and d["contentType"] == "application/json", d)

        b.pages["https://example.com/t"] = FakeResponse(200, {"content-type": "text/plain"}, "plain words")
        s, d = await post(c, {"url": "https://example.com/t"})
        check("text/plain returns the raw body", d["content"] == "plain words", d)

        b.pages["https://example.com/nr"] = FakeResponse(200, {})
        s, d = await post(c, {"url": "https://example.com/nr"})
        check("missing content-type -> contentType null, html content", d["contentType"] is None and "rendered" in d["content"], d)
        check("every scrape closes its context", all(getattr(x, "closed", False) for x in b.contexts), len(b.contexts))
    await with_client(make_cfg(ALLOW_LOCAL_WEBHOOKS="true"), f, t2)

    # 3. failures -> 500 -------------------------------------------------------
    print("-- failures")
    f = Factory()

    async def t3(c):
        b = f.browsers[0]
        b.pages["https://slow.example/"] = TimeoutError("Timeout 1000ms exceeded")
        s, d = await post(c, {"url": "https://slow.example/", "timeout": 1000})
        check("navigation error -> 500 with the generic error", s == 500 and d["error"] == srv.GENERIC_ERROR, (s, d))
        check("500 carries a detail for debugging", "Timeout" in d.get("detail", ""), d)
        b.missing_selectors.add("#never")
        s, d = await post(c, {"url": "https://example.com/", "check_selector": "#never"})
        check("missing check_selector -> 500", s == 500, (s, d))
        s, d = await post(c, {"url": "https://example.com/", "check_selector": "#present"})
        check("present check_selector -> 200", s == 200, (s, d))
        check("failed scrape still closed its context", all(getattr(x, "closed", False) for x in b.contexts))
    await with_client(make_cfg(ALLOW_LOCAL_WEBHOOKS="true"), f, t3)

    # 4. headers / cookies / UA ------------------------------------------------
    print("-- headers, cookies, user agent")
    f = Factory()

    async def t4(c):
        b = f.browsers[0]
        hdr = {"Cookie": "sid=abc; theme=dark", "X-Test": "1", "User-Agent": "CustomBot/9"}
        s, d = await post(c, {"url": "https://www.example.co.uk/x", "headers": hdr, "skip_tls_verification": True})
        ctx = b.contexts[-1]
        names = sorted((x["name"], x["value"]) for x in ctx.cookies)
        check("Cookie header split into individual cookies", ("sid", "abc") in names and ("theme", "dark") in names, names)
        domains = {x["domain"] for x in ctx.cookies}
        check("cookie domain = host (+ parent of www.), never a public suffix like co.uk",
              domains == {".www.example.co.uk", ".example.co.uk"}, domains)
        check("other headers go to new_context(extra_http_headers=...) (UA and Cookie excluded)", ctx.kwargs.get("extra_http_headers") == {"X-Test": "1"}, ctx.kwargs)
        check("a scrape with extra headers succeeds (engine has no set_extra_http_headers)", s == 200, (s, d))
        check("caller User-Agent is NOT applied by default", "user_agent" not in ctx.kwargs, ctx.kwargs)
        check("skip_tls_verification -> ignore_https_errors", ctx.kwargs.get("ignore_https_errors") is True, ctx.kwargs)
        s, d = await post(c, {"url": "https://example.com/"})
        check("no ignore_https_errors unless asked", "ignore_https_errors" not in b.contexts[-1].kwargs, b.contexts[-1].kwargs)
    await with_client(make_cfg(ALLOW_LOCAL_WEBHOOKS="true"), f, t4)

    f = Factory()

    async def t4b(c):
        await post(c, {"url": "https://example.com/", "headers": {"user-agent": "CustomBot/9"}})
        check("INVPW_HONOR_USER_AGENT=true applies the caller's UA", f.browsers[0].contexts[-1].kwargs.get("user_agent") == "CustomBot/9")
    await with_client(make_cfg(ALLOW_LOCAL_WEBHOOKS="true", INVPW_HONOR_USER_AGENT="true"), f, t4b)

    # 5. SSRF guard + interception --------------------------------------------
    print("-- SSRF guard / interception")
    f = Factory()

    async def t5(c):
        for url in ("http://127.0.0.1/", "http://10.1.2.3/x", "http://[::1]/", "http://169.254.169.254/latest",
                    "http://localhost:3000/health"):
            s, d = await post(c, {"url": url})
            check("guard on: %s -> 200 + pageStatusCode 403" % url,
                  s == 200 and d["pageStatusCode"] == 403 and d["content"] == "" and d["pageError"], (s, d))
        for url in ("http://internal.corp/", "http://mixed.example/", "http://no-such-host.invalid/"):
            s, d = await post(c, {"url": url})
            check("guard on: %s (private / mixed / unresolvable) -> 403" % url,
                  s == 200 and d["pageStatusCode"] == 403, (s, d))
        check("blocked targets never reached the browser", not f.browsers[0].log, f.browsers[0].log)
        s, d = await post(c, {"url": "https://example.com/"})
        check("a hostname resolving to a public address is fetched", s == 200 and d["pageStatusCode"] == 200, (s, d))
        f.browsers[0].pages["http://93.184.216.34/"] = FakeResponse(200)
        s, d = await post(c, {"url": "http://93.184.216.34/"})
        check("a public IP literal is fetched", s == 200 and d["pageStatusCode"] == 200, (s, d))
        check("guard on -> requests are routed (per-request check)", f.browsers[0].contexts[-1].routed)
    await with_client(make_cfg(), f, t5)

    f = Factory()

    async def t5b(c):
        s, d = await post(c, {"url": "http://127.0.0.1/"})
        check("ALLOW_LOCAL_WEBHOOKS=true: private address is fetched", s == 200 and d["pageStatusCode"] == 200, (s, d))
        check("nothing needs interception by default -> page.route not used", not f.browsers[0].contexts[-1].routed)
    await with_client(make_cfg(ALLOW_LOCAL_WEBHOOKS="true"), f, t5b)

    # route handler decisions
    class R:
        def __init__(self, url, rtype="document"):
            self.request = type("Q", (), {"url": url, "resource_type": rtype})()
            self.action = None

        async def abort(self, code):
            self.action = "abort"

        async def continue_(self):
            self.action = "continue"

    f = Factory()

    async def t5c(c):
        await post(c, {"url": "https://example.com/"})
        handler = f.browsers[0].contexts[-1].handler
        r1, r2, r3, r4 = (R("https://example.com/p.png", "image"), R("https://ads.doubleclick.net/x", "script"),
                          R("https://example.com/app.js", "script"), R("http://10.0.0.5/", "xhr"))
        for r in (r1, r2, r3, r4):
            await handler(r)
        check("BLOCK_MEDIA aborts images", r1.action == "abort", r1.action)
        check("BLOCK_ADS aborts ad hosts", r2.action == "abort", r2.action)
        check("ordinary requests continue", r3.action == "continue", r3.action)
        check("guard aborts a private subresource", r4.action == "abort", r4.action)
    await with_client(make_cfg(ALLOW_LOCAL_WEBHOOKS="false", BLOCK_MEDIA="true", BLOCK_ADS="true"), f, t5c)

    # 6. concurrency -----------------------------------------------------------
    print("-- concurrency")
    f = Factory()

    async def t6(c):
        f.browsers[0].delay = 0.15
        res = await asyncio.gather(*[post(c, {"url": "https://example.com/%d" % i}) for i in range(5)])
        check("all 5 concurrent scrapes succeed", all(s == 200 for s, _ in res), res)
        check("MAX_CONCURRENT_PAGES=2 is never exceeded (peak %d)" % f.browsers[0].peak, f.browsers[0].peak == 2, f.browsers[0].peak)
    await with_client(make_cfg(ALLOW_LOCAL_WEBHOOKS="true", MAX_CONCURRENT_PAGES="2"), f, t6)

    # 7. health + browser restart ---------------------------------------------
    print("-- health / restart")
    f = Factory()

    async def t7(c):
        r = await c.get("/health")
        d = await r.json()
        check("GET /health -> 200 healthy", r.status == 200 and d["status"] == "healthy" and d["maxConcurrentPages"] == 4, (r.status, d))
        f.browsers[0].connected = False
        s, d = await post(c, {"url": "https://example.com/"})
        check("a dead browser is replaced on the next scrape", s == 200 and f.calls == 2, (s, f.calls))
    await with_client(make_cfg(ALLOW_LOCAL_WEBHOOKS="true"), f, t7)

    f = Factory()
    f.fail = False
    cfg = make_cfg(ALLOW_LOCAL_WEBHOOKS="true")
    cfg.eager_start = False

    async def t7b(c):
        f.fail = True
        r = await c.get("/health")
        d = await r.json()
        check("engine cannot start -> /health 503 unhealthy", r.status == 503 and d["status"] == "unhealthy", (r.status, d))
        s, d = await post(c, {"url": "https://example.com/"})
        check("engine cannot start -> /scrape 500", s == 500, (s, d))
        f.fail = False
        s, d = await post(c, {"url": "https://example.com/"})
        check("service recovers once the engine can start", s == 200, (s, d))
    await with_client(cfg, f, t7b)

    # 8. configuration ---------------------------------------------------------
    print("-- configuration")
    cfg = make_cfg(PROXY_SERVER="proxy.local:8080", PROXY_USERNAME="u", PROXY_PASSWORD="p",
                   INVPW_SEED="42", INVPW_TIMEZONE="Europe/Berlin", INVPW_LOCALE="de-DE")
    check("scheme-less PROXY_SERVER defaults to http://", cfg.proxy == {"server": "http://proxy.local:8080", "username": "u", "password": "p"}, cfg.proxy)
    check("seed / timezone / locale are read", (cfg.seed, cfg.timezone, cfg.locale) == (42, "Europe/Berlin", "de-DE"), (cfg.seed, cfg.timezone, cfg.locale))
    cfg = make_cfg()
    check("defaults: no proxy, auto locale, guard ON, 4 pages, no interception beyond the guard",
          cfg.proxy is None and cfg.locale == "auto" and cfg.ssrf_guard and cfg.max_pages == 4 and not cfg.honor_user_agent, vars(cfg))
    check("ALLOW_LOCAL_WEBHOOKS=true -> nothing intercepted by default", not make_cfg(ALLOW_LOCAL_WEBHOOKS="true").intercept)
    check("junk numeric env falls back to defaults", make_cfg(MAX_CONCURRENT_PAGES="lots").max_pages == 4)

    # 9. the real launcher builds the right kwargs -----------------------------
    print("-- real launcher arguments")
    captured = {}

    class FakeIP:
        def __init__(self, **kw):
            captured["kw"] = kw
            if "timezone" not in kw:
                raise RuntimeError("geoip cold cache")

        async def __aenter__(self):
            return "browser"

        async def __aexit__(self, *a):
            return False

    import types
    mod = types.ModuleType("invisible_playwright")
    sub = types.ModuleType("invisible_playwright.async_api")
    sub.InvisiblePlaywright = FakeIP
    sys.modules["invisible_playwright"], sys.modules["invisible_playwright.async_api"] = mod, sub
    from contextlib import AsyncExitStack
    async with AsyncExitStack() as st:
        got = await srv.launch_invisible(st, make_cfg(INVPW_SEED="7"))
    check("no proxy + cold GeoIP cache: retried with a fixed fallback timezone", got == "browser" and captured["kw"].get("timezone") == "UTC", captured)
    check("launcher passes headless/locale/seed (and no proxy key)", captured["kw"]["headless"] is True and captured["kw"]["locale"] == "auto"
          and captured["kw"]["seed"] == 7 and "proxy" not in captured["kw"], captured)
    async with AsyncExitStack() as st:
        await srv.launch_invisible(st, make_cfg(PROXY_SERVER="socks5://p:1080", PROXY_USERNAME="u", PROXY_PASSWORD="p", INVPW_TIMEZONE="Europe/Paris"))
    check("launcher passes the proxy as {server, username, password}",
          captured["kw"]["proxy"] == {"server": "socks5://p:1080", "username": "u", "password": "p"}, captured)
    refused = None
    async with AsyncExitStack() as st:
        try:
            await srv.launch_invisible(st, make_cfg(PROXY_SERVER="http://p:8080"))
        except RuntimeError as exc:
            refused = str(exc)
    check("behind a proxy a failed GeoIP lookup is NOT papered over with UTC", refused == "geoip cold cache", refused)
    async with AsyncExitStack() as st:
        await srv.launch_invisible(st, make_cfg(INVPW_TIMEZONE="Asia/Tokyo"))
    check("explicit timezone is passed through untouched", captured["kw"]["timezone"] == "Asia/Tokyo", captured)


asyncio.run(main())
print()
print("PASS" if PASS else "FAIL")
sys.exit(0 if PASS else 1)
EOF_TEST_INVISIBLE_SERVICE_PY

# --- e2e_test.sh ---
cat > "$TARGET/e2e_test.sh" <<'EOF_E2E_TEST_SH'
#!/usr/bin/env bash
# End-to-end test of install-local-search.sh:
#   * simulates downloading ONLY the installer (nothing else next to it)
#   * mocks docker so the install logic runs fully
#   * verifies the produced install folder, the ~/.agents/skills/local-web-search
#     skill install, the install-dir.txt hint, and the uninstaller.
#   * CORE-MODE test: the default (no Firecrawl account) install must skip
#     the 19 account-gated tool scripts and install the core-only SKILL.md.
#   * ACCOUNT-MODE test: re-runs the installer with a fake Firecrawl account
#     and verifies all 25 tools install, the credentials land in .env, and
#     firecrawl_api.py picks them up (routing the tools to the cloud API).
#   * SELF-HEAL test: fake SearXNG/Firecrawl HTTP servers + a mock
#     `docker compose up` that starts them, verifying that web_search.py /
#     web_scrape.py auto-start a down stack and retry (and report cleanly
#     when the stack cannot come up).
#   * DOCKER AUTO-START test: a mock docker whose engine is DOWN + a mock
#     systemctl that starts it, verifying the installer launches the engine
#     itself, waits for it, and completes (plus both failure paths).
#   * UNREACHABLE-SITE test: a fake Firecrawl that fails / hangs + pinned DNS/TCP
#     results (fake-IP 198.18.x.x, packets dropped), verifying the scripts explain
#     the blocked route, do not retry or wait on it, and never mistake a slow page
#     for a dead stack (while a reachable site and a cloud Firecrawl keep retrying).
# Any pre-existing ~/.agents/skills/local-web-search is backed up and restored.
set -u

ROOT="$(cd "$(dirname "$0")" && pwd)"
INSTALLER="$ROOT/local-search/install-local-search.sh"
TESTROOT="$ROOT/.ls-test-$$"
SRC_DIR="$TESTROOT/src-only-installer"
TGT_DIR="$TESTROOT/target"
MOCKBIN="$TESTROOT/bin"
SKILL_DIR="$HOME/.agents/skills/local-web-search"
SKILL_BAK=""

PY="$(command -v python3 || command -v python)"
if [ -z "$PY" ]; then
  echo "[ERROR] python3/python is required for this test." >&2
  exit 1
fi

cleanup() {
  rc=$?
  # kill the fake stack server if a self-heal phase left it running
  if [ -f "$TESTROOT/fake_stack.pid" ]; then
    kill "$(cat "$TESTROOT/fake_stack.pid" 2>/dev/null)" 2>/dev/null
    rm -f "$TESTROOT/fake_stack.pid"
  fi
  if [ -f "$TESTROOT/netdiag.pid" ]; then
    kill "$(cat "$TESTROOT/netdiag.pid" 2>/dev/null)" 2>/dev/null
    rm -f "$TESTROOT/netdiag.pid"
  fi
  rm -rf "$SKILL_DIR" 2>/dev/null
  if [ -n "$SKILL_BAK" ] && [ -d "$SKILL_BAK" ]; then
    mv "$SKILL_BAK" "$SKILL_DIR" 2>/dev/null
  fi
  if [ "$rc" = 0 ]; then rm -rf "$TESTROOT"; fi
}
trap cleanup EXIT

mkdir -p "$SRC_DIR" "$TGT_DIR" "$MOCKBIN"

# Back up any real skill install so the test can never destroy it.
if [ -d "$SKILL_DIR" ]; then
  SKILL_BAK="$TESTROOT/skill-backup"
  mv "$SKILL_DIR" "$SKILL_BAK"
fi

# --- mock docker + docker compose so the installer's checks pass -----------
cat > "$MOCKBIN/docker" <<'MOCK'
#!/usr/bin/env bash
case "$1" in
  info)        exit 0 ;;
  compose)
    case "$2" in
      version) echo "Docker Compose version v2.0.0-test"; exit 0 ;;
      pull)    echo "[mock] pull ok";   exit 0 ;;
      up)      echo "[mock] up ok";     exit 0 ;;
      down)    echo "[mock] down ok";   exit 0 ;;
      *)       echo "[mock] docker compose $*"; exit 0 ;;
    esac ;;
  *) echo "[mock] docker $*"; exit 0 ;;
esac
MOCK
chmod +x "$MOCKBIN/docker"
REAL_PATH="$PATH"   # before any mock dir is prepended (used by the engine scenarios)
export PATH="$MOCKBIN:$PATH"

# The scenarios below mock DOCKER. The installer prefers Podman when it is on
# PATH (a dev machine may well have it), so pin the engine here; the Podman /
# auto-detect scenarios further down override this per run. The post-start
# SearXNG check is skipped for the same reason (nothing listens behind a mock);
# it gets its own scenarios below.
export LOCAL_SEARCH_ENGINE=docker
export LOCAL_SEARCH_VERIFY_TIMEOUT=0

# --- copy ONLY the installer .sh into the source folder -------------------
cp "$INSTALLER" "$SRC_DIR/"
chmod +x "$SRC_DIR/install-local-search.sh"

echo "Source folder contents (should be ONLY install-local-search.sh):"
ls -la "$SRC_DIR"
echo

# --- run the installer with scripted answers (CORE MODE: no account) --------
#   Setup type: 3 (full setup, to exercise custom values),
#   Step 1: target folder, Step 2: searxng port, Step 3: firecrawl port,
#   Step 4: browserless? -> n (playwright default), Step 5: connect LLM? -> n,
#   Step 6: Firecrawl account? -> n,  confirm -> y
printf '%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n' \
  "3" \
  "$TGT_DIR" \
  "" \
  "" \
  "n" \
  "n" \
  "n" \
  "y" | "$SRC_DIR/install-local-search.sh" > "$TESTROOT/install.log" 2>&1
RC=$?
echo "Installer exit code: $RC"
echo "----- install.log (tail) -----"
tail -30 "$TESTROOT/install.log"
echo "--------------------------------"

PASS=1
[ "$RC" = 0 ] || PASS=0

# --- verify the target folder has everything we expect --------------------
echo
echo "Target folder contents:"
ls -la "$TGT_DIR"
echo
echo "Target config/searxng contents:"
ls -la "$TGT_DIR/config/searxng"
echo
echo "Target local-web-search contents:"
find "$TGT_DIR/local-web-search" -type f | sort

check() {
  if [ -s "$TGT_DIR/$1" ]; then
    echo "  [OK]   $1  ($(wc -c < "$TGT_DIR/$1") bytes)"
  else
    echo "  [FAIL] $1  (missing or empty)"
    PASS=0
  fi
}
check_absent() {
  if [ -e "$TGT_DIR/$1" ]; then
    echo "  [FAIL] $1  (must NOT be installed without a Firecrawl account)"
    PASS=0
  else
    echo "  [OK]   $1  (absent - core-only install, as expected)"
  fi
}
echo
echo "Checking expected files:"
check "docker-compose.yml"
check ".env.example"
check ".env"
check "README.md"
check "LICENSE"
check ".gitignore"
check ".gitattributes"
check "config/searxng/settings.yml"
check "Run.bat"
check "Stop.bat"
check "Update.bat"
check "Uninstall.bat"
check "run.sh"
check "stop.sh"
check "update.sh"
check "uninstall.sh"
check "engine.sh"
check "local-web-search/SKILL.md"
check "local-web-search/scripts/config.py"
check "local-web-search/scripts/ensure_stack.py"
check "local-web-search/scripts/firecrawl_api.py"
check "local-web-search/scripts/web_search.py"
check "local-web-search/scripts/web_scrape.py"
check "local-web-search/scripts/web_youtube_transcript.py"
check "local-web-search/scripts/web_map.py"
check "local-web-search/scripts/web_crawl.py"
check "local-web-search/scripts/web_crawl_status.py"
check "install-local-search.bat"
check "install-local-search.sh"

# --- core-only mode: the 19 account-gated scripts must NOT be installed ------
echo
echo "Checking the account-gated tools are NOT installed (no Firecrawl account):"
for f in web_agent.py web_agent_status.py web_interact.py web_interact_stop.py \
         web_parse.py web_monitor_create.py web_monitor_list.py \
         web_monitor_get.py web_monitor_update.py web_monitor_delete.py \
         web_monitor_run.py web_monitor_checks.py web_monitor_check.py \
         web_research_search.py web_research_inspect.py web_research_related.py \
         web_research_read.py web_github_search.py web_developer_search.py; do
  check_absent "local-web-search/scripts/$f"
done
check_absent "local-web-search/SKILL-core.md"

# SKILL.md must be the core-only variant (no account tools mentioned)
if grep -qF "Tools: search, scrape, map, crawl, crawl status, YouTube transcripts." "$TGT_DIR/local-web-search/SKILL.md" \
   && ! grep -q "web_monitor_create" "$TGT_DIR/local-web-search/SKILL.md" \
   && ! grep -q "web_developer_search" "$TGT_DIR/local-web-search/SKILL.md"; then
  echo "  [OK]   local-web-search/SKILL.md is the core-only variant"
else
  echo "  [FAIL] local-web-search/SKILL.md is not the core-only variant"
  PASS=0
fi

# verify .env has the chosen ports + a real secret
echo
echo "----- .env contents -----"
cat "$TGT_DIR/.env"
echo "-------------------------"

if grep -q "^SEARXNG_PORT=9990$" "$TGT_DIR/.env" \
   && grep -q "^FIRECRAWL_PORT=9991$" "$TGT_DIR/.env" \
   && grep -q "^SEARXNG_SECRET=[0-9a-f]\{64\}$" "$TGT_DIR/.env"; then
  echo "[OK] .env has correct ports and a 64-hex secret"
else
  echo "[FAIL] .env is malformed"
  PASS=0
fi

# core mode: no Firecrawl account credentials in .env
if grep -q "^FIRECRAWL_API_KEY=" "$TGT_DIR/.env" \
   || grep -q "^FIRECRAWL_API_URL=" "$TGT_DIR/.env"; then
  echo "[FAIL] .env should not contain Firecrawl account credentials (core mode)"
  PASS=0
else
  echo "[OK] .env has no Firecrawl account credentials (core mode)"
fi

# verify the secret got injected into settings.yml (no placeholder left)
if grep -q "__SEARXNG_SECRET_PLACEHOLDER__" "$TGT_DIR/config/searxng/settings.yml"; then
  echo "[FAIL] settings.yml still has the placeholder (injection failed)"
  PASS=0
else
  echo "[OK] settings.yml no longer has the placeholder (secret injected)"
fi

# verify .bat files have CRLF line endings
BAT_HAS_CRLF=1
for f in Run.bat Stop.bat Update.bat Uninstall.bat install-local-search.bat; do
  if ! grep -q $'\r' "$TGT_DIR/$f" 2>/dev/null; then
    echo "[FAIL] $f does not have CRLF line endings"
    BAT_HAS_CRLF=0
  fi
done
[ "$BAT_HAS_CRLF" = 1 ] && echo "[OK] all .bat files have CRLF line endings"

# --- quick-setup test: accepting the new gate's default (Y) must skip -------
#     all six numbered steps and install with the documented defaults ---------
echo
echo "===== minimal install: setup type 1 ====="
QUICKHOME="$TESTROOT/quickhome"
mkdir -p "$QUICKHOME"
printf '1\n' | env HOME="$QUICKHOME" PATH="$MOCKBIN:$PATH" \
  "$SRC_DIR/install-local-search.sh" > "$TESTROOT/quick.log" 2>&1
QRC=$?
echo "Installer exit code: $QRC"
tail -15 "$TESTROOT/quick.log"
echo "--------------------------------"
QTGT="$QUICKHOME/local-search"
if [ "$QRC" = 0 ] && [ -d "$QTGT" ]; then
  echo "[OK] quick-setup installed to the default folder ($QTGT)"
else
  echo "[FAIL] quick-setup did not install to the default folder"; PASS=0
fi
if grep -q "^SEARXNG_PORT=9990$" "$QTGT/.env" 2>/dev/null \
   && grep -q "^FIRECRAWL_PORT=9991$" "$QTGT/.env" 2>/dev/null; then
  echo "[OK] quick-setup used the default ports"
else
  echo "[FAIL] quick-setup did not use the default ports"; PASS=0
fi
if grep -q "^COMPOSE_PROFILES=playwright$" "$QTGT/.env" 2>/dev/null \
   && grep -q "^PLAYWRIGHT_MICROSERVICE_URL=http://playwright-service:3000/scrape$" "$QTGT/.env" 2>/dev/null; then
  echo "[OK] quick-setup defaulted to the Playwright engine"
else
  echo "[FAIL] quick-setup did not default to Playwright"; PASS=0
fi
if grep -q "^FIRECRAWL_API_KEY=" "$QTGT/.env" 2>/dev/null; then
  echo "[FAIL] quick-setup should not have Firecrawl account credentials"; PASS=0
else
  echo "[OK] quick-setup has no Firecrawl account credentials (core mode)"
fi
if [ -d "$QUICKHOME/.agents/skills/local-web-search" ]; then
  echo "[OK] quick-setup installed the local-web-search skill"
else
  echo "[FAIL] quick-setup did not install the local-web-search skill"; PASS=0
fi

# --- Step 4 engine menu: 1/2/3, the old y/n answers, letter aliases, re-prompt ------------
#   Each scenario is a full setup into its own HOME; a logging mock docker records the compose
#   calls so we can check that ONLY the Invisible Playwright engine is built (--build).
echo
echo "===== Step 4: browser engine menu (3 engines) ====="
ENGMOCK="$TESTROOT/engmock"; mkdir -p "$ENGMOCK"
cat > "$ENGMOCK/docker" <<'MOCK'
#!/usr/bin/env bash
echo "docker $*" >> "${ENG_LOG:-/dev/null}"
case "$1" in
  info) exit 0 ;;
  compose) case "$2" in version) echo "Docker Compose version v2.0.0-test" ;; *) echo "[mock] $2 ok" ;; esac; exit 0 ;;
  *) exit 0 ;;
esac
MOCK
chmod +x "$ENGMOCK/docker"
engine_case() {  # engine_case NAME "ANSWER(S) at Step 4, \n separated" EXPECT_PROFILE EXPECT_URL EXPECT_BUILD(yes|no) [EXPECT_WARNING]
  local name="$1" answers="$2" want_prof="$3" want_url="$4" want_build="$5" want_warn="${6:-}"
  local H="$TESTROOT/eng3-$name"; rm -rf "$H"; mkdir -p "$H"
  local T="$H/target" LOG="$TESTROOT/eng3-$name.dockerlog" OUT="$TESTROOT/eng3-$name.log" ok=1
  : > "$LOG"
  printf '3\n%s\n\n\n'"$answers"'\nn\nn\ny\n' "$T" \
    | env HOME="$H" ENG_LOG="$LOG" PATH="$ENGMOCK:$PATH" "$SRC_DIR/install-local-search.sh" > "$OUT" 2>&1 || ok=0
  grep -q "^COMPOSE_PROFILES=$want_prof$" "$T/.env" 2>/dev/null || ok=0
  grep -q "^PLAYWRIGHT_MICROSERVICE_URL=$want_url$" "$T/.env" 2>/dev/null || ok=0
  if [ "$want_build" = yes ]; then
    grep -q "^docker compose up -d --build$" "$LOG" || ok=0
  else
    grep -q "^docker compose up -d$" "$LOG" && ! grep -q -- "--build" "$LOG" || ok=0
  fi
  [ -n "$want_warn" ] && { grep -q "$want_warn" "$OUT" || ok=0; }
  grep -q "^INVISIBLE_GITHUB_TOKEN=$" "$T/.env" 2>/dev/null || ok=0   # block present in every .env
  if [ "$ok" = 1 ]; then echo "  [OK]   engine answer '$name' -> $want_prof (build: $want_build)"
  else echo "  [FAIL] engine answer '$name' -> expected $want_prof / $want_url / build $want_build"; tail -n 12 "$OUT"; PASS=0; fi
}
