        nohup "$FAKE_PY" "$FAKE_STACK" "$SEARXNG_PORT" "$FIRECRAWL_PORT" "$FAKE_PIDFILE" >/dev/null 2>&1 &
        echo "[mock] compose up ok (fake stack started)"
        exit 0 ;;
      *) exit 0 ;;
    esac ;;
  *) exit 0 ;;
esac
MOCK2
