#!/usr/bin/env bash
case "$1" in
  info) exit 0 ;;
  compose)
    case "$2" in
      version) echo "Docker Compose version v2.0.0-test"; exit 0 ;;
      up) echo "[mock] compose up ok (nothing actually started)"; exit 0 ;;
      *) exit 0 ;;
    esac ;;
  *) exit 0 ;;
esac
MOCK3
