  HEAL_ENV="FAKE_PY=$PY FAKE_STACK=$TESTROOT/fake_stack.py FAKE_PIDFILE=$FAKE_PIDFILE LOCAL_SEARCH_DIR=$TGT_DIR"

  # Phase A - fast path: stack already up -> straight to results, no boot
