    echo "  [OK]   self-heal: web_search booted the down stack and retried"
  else
    echo "  [FAIL] web_search self-heal"; cat "$TESTROOT/healB.log"; PASS=0
  fi

  # Phase B2 - self-heal for the scraper
  kill_fake_stack
  if env $HEAL_ENV PATH="$TESTROOT/bin2:$PATH" \
       "$PY" "$SKILL_DIR/scripts/web_scrape.py" "https://example.com/article" \
       > "$TESTROOT/healB2.log" 2>&1 \
     && grep -q "starting it automatically" "$TESTROOT/healB2.log" \
     && grep -q "FAKE MARKDOWN" "$TESTROOT/healB2.log"; then
    echo "  [OK]   self-heal: web_scrape booted the down stack and retried"
  else
    echo "  [FAIL] web_scrape self-heal"; cat "$TESTROOT/healB2.log"; PASS=0
  fi

  # Phase C - failure: stack cannot come up -> clear guidance, exit 1
  kill_fake_stack
  if env $HEAL_ENV PATH="$TESTROOT/bin3:$PATH" LOCAL_SEARCH_READY_TIMEOUT=2 \
       "$PY" "$SKILL_DIR/scripts/web_search.py" "doomed" \
       > "$TESTROOT/healC.log" 2>&1; then
    echo "  [FAIL] self-heal failure path should exit non-zero"; PASS=0
  elif grep -q "could not be started" "$TESTROOT/healC.log" \
       && grep -q "did not become ready" "$TESTROOT/healC.log"; then
    echo "  [OK]   self-heal failure: clear guidance, non-zero exit"
  else
    echo "  [FAIL] self-heal failure message missing"; cat "$TESTROOT/healC.log"; PASS=0
  fi
  # Phase D - self-heal through PODMAN: same fake stack, a podman mock beside the
  # docker mock. The explicit override beats the engine recorded in .env; with the
  # recorded engine removed, auto-detection must prefer Podman over Docker.
  mkdir -p "$TESTROOT/bin2p"
  cat > "$TESTROOT/bin2p/podman" <<'MOCK2P'
#!/usr/bin/env bash
case "$1" in
  info)
    case "${3:-}" in *RemoteSocket*) echo true ;; *Rootless*) echo false ;; esac
    exit 0 ;;
  compose)
    case "$2" in
      version) echo "Compose v2.0.0-test"; exit 0 ;;
      up)
        SEARXNG_PORT=$(grep -E '^SEARXNG_PORT=' .env | cut -d= -f2)
        FIRECRAWL_PORT=$(grep -E '^FIRECRAWL_PORT=' .env | cut -d= -f2)
        echo podman >> "$ENGINE_MARK"
        nohup "$FAKE_PY" "$FAKE_STACK" "$SEARXNG_PORT" "$FIRECRAWL_PORT" "$FAKE_PIDFILE" >/dev/null 2>&1 &
        echo "[mock] podman compose up ok (fake stack started)"
        exit 0 ;;
      *) exit 0 ;;
    esac ;;
  *) exit 0 ;;
esac
MOCK2P
  chmod +x "$TESTROOT/bin2p/podman"
  NOENG="$TESTROOT/inst-noeng"; rm -rf "$NOENG"; cp -r "$TGT_DIR" "$NOENG"
  sed -i.bak '/^LOCAL_SEARCH_ENGINE=/d' "$NOENG/.env" && rm -f "$NOENG/.env.bak"

  kill_fake_stack; MARK="$TESTROOT/engine.mark1"; rm -f "$MARK"
  if env $HEAL_ENV ENGINE_MARK="$MARK" LOCAL_SEARCH_ENGINE=podman PATH="$TESTROOT/bin2p:$TESTROOT/bin2:$PATH" \
       "$PY" "$SKILL_DIR/scripts/web_search.py" "podman heal" > "$TESTROOT/healD.log" 2>&1 \
     && grep -q "FAKE RESULT for podman heal" "$TESTROOT/healD.log" \
     && [ "$(cat "$MARK" 2>/dev/null)" = "podman" ]; then
    echo "  [OK]   self-heal via Podman: LOCAL_SEARCH_ENGINE=podman beats the engine recorded in .env"
  else
    echo "  [FAIL] Podman self-heal (override)"; cat "$TESTROOT/healD.log"; cat "$MARK" 2>/dev/null; PASS=0
