    ("web_agent_status",     "/v1/agent"),
    ("web_interact",         "/v1/interact"),
    ("web_interact_stop",    "/v1/interact"),
    ("web_parse",            "/v1/parse"),
    ("web_monitor_create",   "/v1/monitor"),
    ("web_monitor_list",     "/v1/monitor"),
    ("web_monitor_get",      "/v1/monitor"),
    ("web_monitor_update",   "/v1/monitor"),
    ("web_monitor_delete",   "/v1/monitor"),
    ("web_monitor_run",      "/v1/monitor"),
    ("web_monitor_checks",   "/v1/monitor"),
    ("web_monitor_check",    "/v1/monitor"),
    ("web_research_search",  "/v1/research/search/papers"),
    ("web_research_inspect", "/v1/research/papers"),
    ("web_research_related", "/v1/research/related"),
    ("web_research_read",    "/v1/research/papers"),
    ("web_github_search",    "/v1/research/search/github"),
    ("web_developer_search", "/v1/developer/search"),
]
for name, suffix in checks:
    mod = __import__(name)
    endpoint = mod.ENDPOINT
    if endpoint.startswith("https://api.firecrawl.dev") and endpoint.endswith(suffix):
        print("  [OK]   %s.ENDPOINT = %s" % (name, endpoint))
    else:
        print("  [FAIL] %s.ENDPOINT = %s (expected cloud API + %s)" % (name, endpoint, suffix))
        sys.exit(1)
print("  [OK]   all 22 Firecrawl tool scripts route to the cloud API")
PYEOF4
[ $? = 0 ] || PASS=0

# --- docker auto-start test: engine down -> installer starts it ----------
echo
echo "===== docker auto-start test: installer boots a down engine ====="

# mock docker #4: engine DOWN until a mock 'systemctl start' flips it up
mkdir -p "$TESTROOT/bin4"
cat > "$TESTROOT/bin4/docker" <<'MOCK4'
#!/usr/bin/env bash
case "$1" in
  info)
    [ -f "$DOCKER_UP_MARKER" ] && exit 0
    exit 1 ;;
  compose)
    case "$2" in
      version) echo "Docker Compose version v2.0.0-test"; exit 0 ;;
      *) echo "[mock] ok"; exit 0 ;;
    esac ;;
  *) exit 0 ;;
esac
MOCK4
cat > "$TESTROOT/bin4/systemctl" <<'MOCK4S'
#!/usr/bin/env bash
# mock systemd control: 'start <unit>' brings the engine up
[ "$1" = "start" ] && : > "$DOCKER_UP_MARKER"
exit 0
MOCK4S
chmod +x "$TESTROOT/bin4/docker" "$TESTROOT/bin4/systemctl"

TGT2="$TESTROOT/target2"
UPMARK="$TESTROOT/docker_up.marker"
printf '%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n' "3" "$TGT2" "" "" "n" "n" "n" "y" \
  | env DOCKER_UP_MARKER="$UPMARK" PATH="$TESTROOT/bin4:$PATH" \
    "$SRC_DIR/install-local-search.sh" > "$TESTROOT/instD.log" 2>&1
DRC=$?
if [ "$DRC" = 0 ] && grep -q "trying to start it" "$TESTROOT/instD.log" \
   && grep -q "Launched Docker in the background" "$TESTROOT/instD.log" \
   && grep -q "engine is online" "$TESTROOT/instD.log" \
   && [ -f "$UPMARK" ] && [ -s "$TGT2/docker-compose.yml" ]; then
  echo "  [OK]   auto-start: installer launched the engine, waited, finished"
else
  echo "  [FAIL] docker auto-start install"; tail -20 "$TESTROOT/instD.log"; PASS=0
fi

# mock docker #5: engine down and NOTHING can start it -> clean failure
mkdir -p "$TESTROOT/bin5"
cat > "$TESTROOT/bin5/docker" <<'MOCK5'
#!/usr/bin/env bash
case "$1" in
  info) exit 1 ;;
  *) exit 0 ;;
esac
MOCK5
chmod +x "$TESTROOT/bin5/docker"
for m in systemctl service sudo; do
  printf '#!/usr/bin/env bash\nexit 1\n' > "$TESTROOT/bin5/$m"
  chmod +x "$TESTROOT/bin5/$m"
done
printf '%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n' "3" "$TESTROOT/target5" "" "" "n" "n" "n" "y" \
  | env PATH="$TESTROOT/bin5:$PATH" "$SRC_DIR/install-local-search.sh" \
    > "$TESTROOT/instD2.log" 2>&1
D2RC=$?
if [ "$D2RC" != 0 ] \
   && grep -q "Could not start the Docker engine" "$TESTROOT/instD2.log"; then
  echo "  [OK]   auto-start failure: clean error + exit 1 when nothing can start it"
else
  echo "  [FAIL] expected clean failure when the engine cannot be started"
  tail -20 "$TESTROOT/instD2.log"; PASS=0
fi

# mock docker #6: systemctl 'starts' the engine but docker info never works
mkdir -p "$TESTROOT/bin6"
cp "$TESTROOT/bin5/docker" "$TESTROOT/bin6/docker"
printf '#!/usr/bin/env bash\nexit 0\n' > "$TESTROOT/bin6/systemctl"
chmod +x "$TESTROOT/bin6/docker" "$TESTROOT/bin6/systemctl"
printf '%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n' "3" "$TESTROOT/target6" "" "" "n" "n" "n" "y" \
  | env LOCAL_SEARCH_DOCKER_TIMEOUT=2 PATH="$TESTROOT/bin6:$PATH" \
    "$SRC_DIR/install-local-search.sh" > "$TESTROOT/instD3.log" 2>&1
D3RC=$?
if [ "$D3RC" != 0 ] && grep -q "did not come online" "$TESTROOT/instD3.log"; then
  echo "  [OK]   engine-wait timeout: clean error after LOCAL_SEARCH_DOCKER_TIMEOUT"
else
  echo "  [FAIL] expected timeout failure when the engine never comes online"
  tail -20 "$TESTROOT/instD3.log"; PASS=0
fi

# --- run.sh / update.sh / uninstall.sh also boot a down engine -------------
# TGT2 was installed above with the mock docker #4. LS_ENGINE_POLL=1 keeps the waits short.
echo
echo "===== run.sh / update.sh / uninstall.sh: engine down -> started automatically ====="
AS_ENV() { env DOCKER_UP_MARKER="$UPMARK" LS_ENGINE_POLL=1 "$@"; }

rm -f "$UPMARK"
AS_ENV PATH="$TESTROOT/bin4:$PATH" "$TGT2/run.sh" > "$TESTROOT/as-run.log" 2>&1; ASRC=$?
if [ "$ASRC" = 0 ] && grep -q "trying to start it" "$TESTROOT/as-run.log" \
   && grep -q "Launched Docker in the background" "$TESTROOT/as-run.log" \
   && grep -q "engine is online" "$TESTROOT/as-run.log" \
   && grep -q "Local Search is running" "$TESTROOT/as-run.log" && [ -f "$UPMARK" ]; then
  echo "  [OK]   run.sh: engine down -> launched, waited, stack started"
else
  echo "  [FAIL] run.sh did not start a down engine"; tail -15 "$TESTROOT/as-run.log"; PASS=0
fi

rm -f "$UPMARK"
AS_ENV PATH="$TESTROOT/bin4:$PATH" "$TGT2/update.sh" > "$TESTROOT/as-upd.log" 2>&1
if grep -q "engine is online" "$TESTROOT/as-upd.log" && grep -q "Updating Local Search" "$TESTROOT/as-upd.log"; then
  echo "  [OK]   update.sh: engine down -> launched, then the update ran"
else
  echo "  [FAIL] update.sh did not start a down engine"; tail -15 "$TESTROOT/as-upd.log"; PASS=0
fi

rm -f "$UPMARK"
AS_ENV PATH="$TESTROOT/bin4:$PATH" "$TGT2/run.sh" > /dev/null 2>&1; rm -f "$UPMARK"   # (leave it down again)
# engine up already: no launch message at all
: > "$UPMARK"
AS_ENV PATH="$TESTROOT/bin4:$PATH" "$TGT2/run.sh" > "$TESTROOT/as-run-up.log" 2>&1
if ! grep -q "trying to start it" "$TESTROOT/as-run-up.log" && grep -q "Local Search is running" "$TESTROOT/as-run-up.log"; then
  echo "  [OK]   run.sh with the engine already up: no launch attempt"
else
  echo "  [FAIL] run.sh tried to launch a running engine"; tail -10 "$TESTROOT/as-run-up.log"; PASS=0
fi

# nothing can start it -> clean error, non-zero
AS_ENV PATH="$TESTROOT/bin5:$PATH" "$TGT2/run.sh" > "$TESTROOT/as-run-fail.log" 2>&1; ASFRC=$?
if [ "$ASFRC" != 0 ] && grep -q "could not be started automatically" "$TESTROOT/as-run-fail.log"; then
  echo "  [OK]   run.sh: engine cannot be started -> clean error + exit 1"
else
  echo "  [FAIL] run.sh failure handling"; tail -10 "$TESTROOT/as-run-fail.log"; PASS=0
fi

# 'started' but never answers -> timeout error
AS_ENV LOCAL_SEARCH_DOCKER_TIMEOUT=2 PATH="$TESTROOT/bin6:$PATH" "$TGT2/run.sh" > "$TESTROOT/as-run-to.log" 2>&1; ASTRC=$?
if [ "$ASTRC" != 0 ] && grep -q "did not come online within 2s" "$TESTROOT/as-run-to.log"; then
  echo "  [OK]   run.sh: engine never comes online -> timeout error + exit 1"
else
  echo "  [FAIL] run.sh timeout handling"; tail -10 "$TESTROOT/as-run-to.log"; PASS=0
fi

# uninstall.sh, engine down and startable: asks first, then starts the engine, then removes
mkdir -p "$TESTROOT/h-as/.agents/skills/local-web-search"
rm -f "$UPMARK"
printf 'y\nn\n' | AS_ENV HOME="$TESTROOT/h-as" PATH="$TESTROOT/bin4:$PATH" "$TGT2/uninstall.sh" > "$TESTROOT/as-un.log" 2>&1; ASURC=$?
if [ "$ASURC" = 0 ] && grep -q "engine is online" "$TESTROOT/as-un.log" \
   && [ "$(grep -n 'Continue with uninstall' "$TESTROOT/as-un.log" | head -1 | cut -d: -f1)" -le "$(grep -n 'trying to start it' "$TESTROOT/as-un.log" | head -1 | cut -d: -f1)" ] \
   && grep -q "Containers and volumes removed" "$TESTROOT/as-un.log" \
   && [ ! -d "$TESTROOT/h-as/.agents/skills/local-web-search" ]; then
  echo "  [OK]   uninstall.sh: engine down -> asked first, started it, removed everything"
else
  echo "  [FAIL] uninstall.sh did not start a down engine"; tail -20 "$TESTROOT/as-un.log"; PASS=0
fi

# uninstall.sh, engine cannot be started: nothing is removed (skill and folder stay)
mkdir -p "$TESTROOT/h-as/.agents/skills/local-web-search"
printf 'y\ny\n' | AS_ENV HOME="$TESTROOT/h-as" PATH="$TESTROOT/bin5:$PATH" "$TGT2/uninstall.sh" > "$TESTROOT/as-un2.log" 2>&1; ASU2RC=$?
if [ "$ASU2RC" != 0 ] && grep -q "Nothing was removed" "$TESTROOT/as-un2.log" \
   && [ -d "$TESTROOT/h-as/.agents/skills/local-web-search" ] && [ -f "$TGT2/.env" ]; then
  echo "  [OK]   uninstall.sh: engine cannot be started -> nothing removed, clear message"
else
  echo "  [FAIL] uninstall.sh must not delete anything when the engine is down"; tail -20 "$TESTROOT/as-un2.log"; PASS=0
fi

# Windows scripts: the same start-and-wait block is in Run.bat, Update.bat and Uninstall.bat
python3 - "$SRC_DIR" "$TGT2" <<'PYEOF5'
import re, sys
d = sys.argv[2]
blocks = {}
for n in ("Run.bat", "Update.bat", "Uninstall.bat"):
    t = open(f"{d}/{n}", newline="").read().replace("\r\n", "\n")
    m = re.search(r"^:start_docker\n.*", t, re.S | re.M)
    ok = bool(m) and "call :start_docker" in t and ":docker_ready" in t and "Docker Desktop.exe" in t
    blocks[n] = m.group(0) if m else None
    print(f"  [{'OK' if ok else 'FAIL'}]   {n}: starts Docker Desktop when the engine is down")
    if not ok: sys.exit(1)
if len(set(blocks.values())) != 1:
    print("  [FAIL]   the :start_docker block differs between Run.bat / Update.bat / Uninstall.bat"); sys.exit(1)
print("  [OK]   the :start_docker block is identical in all three .bat scripts")
PYEOF5
[ $? = 0 ] || PASS=0

# --- LLM gating: web_extract.py and the SKILL "LLM extraction" section ship only with an LLM
echo
echo "===== LLM gating: scripts and skill section follow the LLM choice ====="
llm_scenario() {  # llm_scenario LABEL HOMEDIR TARGET EXPECT_LLM(yes|no) EXPECT_ACCOUNT(yes|no); answers on stdin
  local label="$1" h="$2" t="$3" want="$4" acct="$5"
  mkdir -p "$h"
  env HOME="$h" PATH="$MOCKBIN:$PATH" "$SRC_DIR/install-local-search.sh" > "$TESTROOT/llm-$label.log" 2>&1
  local rc=$? sd="$h/.agents/skills/local-web-search" ok=1
  [ "$rc" = 0 ] || { echo "  [FAIL] $label: installer exit code $rc"; ok=0; }
  for d in "$t/local-web-search" "$sd"; do
    if [ "$want" = yes ]; then
      [ -s "$d/scripts/web_extract.py" ] && grep -q "^## LLM extraction" "$d/SKILL.md" \
        || { echo "  [FAIL] $label: web_extract.py / LLM section missing in $d"; ok=0; }
    else
      [ ! -e "$d/scripts/web_extract.py" ] && ! grep -qi "LLM" "$d/SKILL.md" \
        || { echo "  [FAIL] $label: LLM extraction present in $d without an LLM"; ok=0; }
    fi
    [ ! -e "$d/SKILL-llm.md" ] && [ ! -e "$d/SKILL-core.md" ] \
      || { echo "  [FAIL] $label: build-time SKILL variant leaked into $d"; ok=0; }
    if [ "$acct" = yes ]; then
      [ -s "$d/scripts/web_monitor_create.py" ] || { echo "  [FAIL] $label: account tools missing in $d"; ok=0; }
    else
      [ ! -e "$d/scripts/web_monitor_create.py" ] || { echo "  [FAIL] $label: account tools present in $d"; ok=0; }
    fi
  done
  if [ "$ok" = 1 ]; then echo "  [OK]   $label"; else tail -15 "$TESTROOT/llm-$label.log"; PASS=0; fi
}
# setup 2 with explicit endpoint, key and model
llm_scenario opt2 "$TESTROOT/home-opt2" "$TESTROOT/home-opt2/local-search" yes no < <(printf '%s\n' 2 "http://localhost:8080/v1" "sk-e2e-key" "my-model" "y")
if grep -qx "OPENAI_BASE_URL=http://host.docker.internal:8080/v1" "$TESTROOT/home-opt2/local-search/.env" \
   && grep -qx "OPENAI_API_KEY=sk-e2e-key" "$TESTROOT/home-opt2/local-search/.env" \
   && grep -qx "MODEL_NAME=my-model" "$TESTROOT/home-opt2/local-search/.env"; then
  echo "  [OK]   opt2: .env holds base URL (localhost rewritten for the container), key and model"
else
  echo "  [FAIL] opt2: .env LLM settings wrong"; grep -E "OPENAI|MODEL" "$TESTROOT/home-opt2/local-search/.env"; PASS=0
fi
# Enter at the setup-type prompt selects setup 1 (minimal): no LLM anywhere
llm_scenario enter "$TESTROOT/home-enter" "$TESTROOT/home-enter/local-search" no no < <(printf '\n')
if ! grep -q "^OPENAI_" "$TESTROOT/home-enter/local-search/.env"; then
  echo "  [OK]   enter: minimal install, no LLM settings in .env"
else
  echo "  [FAIL] enter: LLM settings written without choosing an LLM"; PASS=0
fi
# setup 3, Step 5 left at its default (Enter = no): no LLM anywhere
llm_scenario opt3-nollm "$TESTROOT/home-opt3n" "$TESTROOT/target-opt3n" no no < <(printf '%s\n' 3 "$TESTROOT/target-opt3n" "" "" "n" "" "n" "y")
# setup 3, LLM answered y with default endpoint, key and model, plus a Firecrawl account: every feature installed
llm_scenario opt3-all "$TESTROOT/home-opt3y" "$TESTROOT/target-opt3y" yes yes < <(printf '%s\n' 3 "$TESTROOT/target-opt3y" "" "" "n" "y" "" "" "" "y" "fc-llm-key" "" "y")
# invalid setup type is re-asked, then 1 selects the minimal install
llm_scenario invalid "$TESTROOT/home-inv" "$TESTROOT/home-inv/local-search" no no < <(printf '%s\n' x 9 1)
grep -q "Please enter 1, 2 or 3" "$TESTROOT/llm-invalid.log" \
  && echo "  [OK]   invalid setup type re-prompts" \
  || { echo "  [FAIL] invalid setup type was not re-prompted"; PASS=0; }

# =============================================================================
#  Container-engine scenarios: Podman preferred, Docker fallback, SELinux, rootless
#  Every tool on PATH is a mock (or a symlink farm of the real system tools with
#  podman/docker/getenforce/systemctl/service/sudo removed), so the result does
#  not depend on what is installed on the machine running the tests.
# =============================================================================
echo
echo "===== container engine: Podman preferred, Docker fallback, SELinux, rootless ====="

MK="$TESTROOT/mocks"; mkdir -p "$MK"

# One generic mock used as both `podman` and `docker`. Behaviour per run via env:
#   MOCK_LOG                file that records every call ("<tool> <args>")
#   MOCK_PODMAN_UP/MOCK_DOCKER_UP=0         `info` fails (engine not running)
#   MOCK_PODMAN_NOCOMPOSE/MOCK_DOCKER_NOCOMPOSE=1   `compose version` fails
#   MOCK_ROOTLESS=true      `podman info --format {{.Host.Security.Rootless}}`
#   MOCK_COMPOSE_LOGS       what `compose logs` prints
mock_engine() {  # mock_engine DIR NAME
  mkdir -p "$1"
  cat > "$1/$2" <<'ENGMOCK'
#!/usr/bin/env bash
me="$(basename "$0")"; ME="$(printf '%s' "$me" | tr a-z A-Z)"
[ -n "${MOCK_LOG:-}" ] && printf '%s %s\n' "$me" "$*" >> "$MOCK_LOG"
upvar="MOCK_${ME}_UP"; nocomp="MOCK_${ME}_NOCOMPOSE"
case "$1" in
  info)
    [ "${!upvar:-1}" = 1 ] || exit 1
    case "${3:-}" in
      *Rootless*)     echo "${MOCK_ROOTLESS:-false}" ;;
      *RemoteSocket*) echo "true" ;;
    esac
    exit 0 ;;
  machine) exit 1 ;;
  exec)   # `<engine> exec <container> <cmd...>`: what the stack sees from the inside
    if [ "$3" = env ]; then      # container environment; the override's blanking removes MOCK_CONTAINER_ENV
      if [ "${MOCK_PROXY_STICKY:-0}" = 1 ] || ! grep -q "^# ls-proxy-vars: ." ./docker-compose.override.yml 2>/dev/null; then
        printf '%s\n' "${MOCK_CONTAINER_ENV:-PATH=/usr/bin}"
      fi
      exit 0
    fi
    exit 0 ;;
  compose)
    case "$2" in
      version) [ "${!nocomp:-0}" = 1 ] && exit 1; echo "Compose v2.0.0-test"; exit 0 ;;
      logs)    printf '%s\n' "${MOCK_COMPOSE_LOGS:-}"; exit 0 ;;
      ps)      echo "mock-ps-output"; exit 0 ;;
      *)       exit 0 ;;
    esac ;;
  *) exit 0 ;;
esac
ENGMOCK
  chmod +x "$1/$2"
}
mock_engine "$MK/podman" podman
mock_engine "$MK/docker" docker
for st in on off; do
  mkdir -p "$MK/se-$st"
  printf '#!/usr/bin/env bash\necho %s\n' "$([ $st = on ] && echo Enforcing || echo Disabled)" > "$MK/se-$st/getenforce"
  chmod +x "$MK/se-$st/getenforce"
done

# symlink farm of the real tools minus everything engine/service related
CLEAN="$MK/clean"; mkdir -p "$CLEAN"
IFS=: read -r -a _real_dirs <<< "$REAL_PATH"
for _d in "${_real_dirs[@]}"; do
  [ -d "$_d" ] || continue
  for _f in "$_d"/*; do
    _b="${_f##*/}"
    case "$_b" in podman|podman-compose|docker|docker-compose|getenforce|systemctl|service|sudo) continue ;; esac
    if [ -f "$_f" ] && [ -x "$_f" ] && [ ! -e "$CLEAN/$_b" ]; then ln -s "$_f" "$CLEAN/$_b"; fi
  done
done

ANS='1\n'   # installer answers: setup type 1 (minimal) unless a scenario overrides
run_install() {  # run_install LABEL PATH HOME [VAR=val ...]  -> RUN_RC, log in $TESTROOT/eng-LABEL.log
  local label="$1" pth="$2" h="$3"; shift 3
  mkdir -p "$h"
  printf "$ANS" | env -u LOCAL_SEARCH_ENGINE HOME="$h" PATH="$pth" "$@" \
      "$SRC_DIR/install-local-search.sh" > "$TESTROOT/eng-$label.log" 2>&1
  RUN_RC=$?
}
eng_check() {  # eng_check DESCRIPTION  (reads the exit status of the previous test)
  if [ "$?" = 0 ]; then echo "  [OK]   $1"; else echo "  [FAIL] $1"; PASS=0; fi
}
envval() { grep -E "^$2=" "$1" 2>/dev/null | tail -n 1 | cut -d= -f2-; }

P_BOTH="$MK/podman:$MK/docker:$MK/se-off:$CLEAN"

# 1. both installed and running -> Podman wins; nothing goes through docker
S1_LOG="$TESTROOT/s1.calls"; : > "$S1_LOG"
run_install s1 "$P_BOTH" "$TESTROOT/h-s1" MOCK_LOG="$S1_LOG"
S1_ENV="$TESTROOT/h-s1/local-search/.env"
[ "$RUN_RC" = 0 ] && grep -q "Podman and its compose tool" "$TESTROOT/eng-s1.log"
eng_check "both installed: installer picked Podman"
grep -q "^podman compose pull" "$S1_LOG" && grep -q "^podman compose up -d" "$S1_LOG" && ! grep -q "^docker compose" "$S1_LOG"
eng_check "both installed: pull + up ran through 'podman compose', never docker"
[ "$(envval "$S1_ENV" LOCAL_SEARCH_ENGINE)" = podman ]
eng_check "both installed: .env records LOCAL_SEARCH_ENGINE=podman"
[ -z "$(envval "$S1_ENV" SEARXNG_MOUNT_OPTS)" ] && [ "$(envval "$S1_ENV" SEARXNG_FORCE_OWNERSHIP)" = true ]
eng_check "no SELinux + rootful: SEARXNG_MOUNT_OPTS empty, SEARXNG_FORCE_OWNERSHIP=true"

# 2. SELinux + rootless Podman -> ,z label, no re-chown, readable config folder
S2_LOG="$TESTROOT/s2.calls"; : > "$S2_LOG"
run_install s2 "$MK/podman:$MK/docker:$MK/se-on:$CLEAN" "$TESTROOT/h-s2" MOCK_LOG="$S2_LOG" MOCK_ROOTLESS=true
S2_ENV="$TESTROOT/h-s2/local-search/.env"
[ "$RUN_RC" = 0 ] && [ "$(envval "$S2_ENV" SEARXNG_MOUNT_OPTS)" = ",z" ] \
  && [ "$(envval "$S2_ENV" SEARXNG_FORCE_OWNERSHIP)" = false ]
eng_check "SELinux + rootless Podman: SEARXNG_MOUNT_OPTS=,z and SEARXNG_FORCE_OWNERSHIP=false"
grep -q "SELinux detected" "$TESTROOT/eng-s2.log" && grep -q "Rootless Podman detected" "$TESTROOT/eng-s2.log"
eng_check "SELinux + rootless Podman: the installer says so"
[ "$(stat -c %a "$TESTROOT/h-s2/local-search/config/searxng" 2>/dev/null || stat -f %Lp "$TESTROOT/h-s2/local-search/config/searxng")" = 755 ] \
  && [ "$(stat -c %a "$TESTROOT/h-s2/local-search/config/searxng/settings.yml" 2>/dev/null || stat -f %Lp "$TESTROOT/h-s2/local-search/config/searxng/settings.yml")" = 644 ]
eng_check "config/searxng is 755 and settings.yml 644 (readable by the container user)"

# 2b. SELinux + Docker (rootful): label yes, ownership switch stays true
run_install s2b "$MK/docker:$MK/se-on:$CLEAN" "$TESTROOT/h-s2b"
S2B_ENV="$TESTROOT/h-s2b/local-search/.env"
[ "$RUN_RC" = 0 ] && [ "$(envval "$S2B_ENV" LOCAL_SEARCH_ENGINE)" = docker ] \
  && [ "$(envval "$S2B_ENV" SEARXNG_MOUNT_OPTS)" = ",z" ] && [ "$(envval "$S2B_ENV" SEARXNG_FORCE_OWNERSHIP)" = true ]
eng_check "SELinux + Docker: ,z label, ownership untouched (true), engine=docker"

# 3. Podman not installed -> Docker
S3_LOG="$TESTROOT/s3.calls"; : > "$S3_LOG"
run_install s3 "$MK/docker:$MK/se-off:$CLEAN" "$TESTROOT/h-s3" MOCK_LOG="$S3_LOG"
[ "$RUN_RC" = 0 ] && grep -q "^docker compose up -d" "$S3_LOG" && grep -q "Docker and its compose tool" "$TESTROOT/eng-s3.log" \
  && [ "$(envval "$TESTROOT/h-s3/local-search/.env" LOCAL_SEARCH_ENGINE)" = docker ]
eng_check "only Docker installed: installer uses Docker"

